const helpAllowed_=topic=>topic.view==='dashboard'||allowed(topic.view);
function helpNormalize_(value){return latinDigits_(value).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f\u064b-\u065f\u0670]/g,'').replace(/[أإآ]/g,'ا').replace(/ة/g,'ه').replace(/ى/g,'ي').replace(/ؤ/g,'و').replace(/ئ/g,'ي').replace(/[^a-z0-9\u0600-\u06ff]+/g,' ').trim()}
function helpExpand_(query){let q=helpNormalize_(query);const groups=[['اطبع','طباعه','pdf','برنت','print'],['فلوس','مبلغ','دفعه','دفع','قبض','تحصيل','payment','money'],['مشروع','موقع','project'],['عميل','زبون','customer','client'],['مورد','مقاول','صنايعي','supplier','contractor'],['مرتب','راتب','اجور','salary','payroll'],['بنك','حساب','سيوله','bank','account'],['عدل','تعديل','غير','تصحيح','edit','change'],['مشكله','خطا','مش شغال','error','failed']];for(const group of groups)if(group.some(x=>q.includes(helpNormalize_(x))))q+=' '+group.map(helpNormalize_).join(' ');return q}
function helpEditDistance_(a,b){if(!a)return b.length;if(!b)return a.length;const row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const tmp=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=tmp}}return row[b.length]}
function helpIntentBoost_(topic,query){const q=helpNormalize_(query),has=(...words)=>words.some(x=>q.includes(helpNormalize_(x))),all=(a,b)=>has(...a)&&has(...b);let score=0;if(topic.id==='clientReport'&&all(['اطبع','طبعت','طباعه','كشف','فاتوره','print'],['مشروع','عميل','project','client']))score+=90;if(topic.id==='supplierReport'&&all(['كشف','حساب','statement','اطبع'],['مورد','مقاول','supplier','contractor']))score+=90;if(topic.id==='reconcile'&&all(['بنك','bank'],['كشف','مطابقه','statement','statment','reconcile']))score+=90;if(topic.id==='transaction'&&all(['فلوس','مبلغ','دفعه','قبض','تحصيل','money','payment'],['دخلت','داخله','عميل','زبون','received','income']))score+=80;if(topic.id==='project'&&all(['عدل','غير','تعديل','edit','change'],['مشروع','موقع','project']))score+=80;if(topic.id==='client'&&all(['عدل','غير','تعديل','edit','change'],['عميل','زبون','client']))score+=80;if(topic.id==='employees'&&has('مرتب','راتب','مرتبات','اجور','payroll','salary'))score+=55;if(topic.id==='errors'&&has('مشكله','خطا','مش شغال','فشل','error','failed'))score+=55;return score}
function helpScore_(topic,query){const q=helpExpand_(query),words=q.split(' ').filter(Boolean),hay=helpNormalize_([topic.titleAr,topic.titleEn,topic.keys,...topic.stepsAr,...topic.stepsEn].join(' ')),tokens=new Set(hay.split(' '));if(!q)return 1;let score=(hay.includes(q)?60:0)+helpIntentBoost_(topic,query);for(const word of words){if(tokens.has(word))score+=12;else if([...tokens].some(x=>x.includes(word)||word.includes(x)))score+=6;else if(word.length>3&&[...tokens].some(x=>Math.abs(x.length-word.length)<=2&&helpEditDistance_(x,word)<=2))score+=3}return score}
function helpResults_(query=''){return HELP_TOPICS.filter(helpAllowed_).map(x=>({topic:x,score:helpScore_(x,query)})).filter(x=>!query||x.score>0).sort((a,b)=>b.score-a.score||a.topic.titleAr.localeCompare(b.topic.titleAr)).slice(0,query?8:HELP_TOPICS.length).map(x=>x.topic)}
function helpCard_(topic){const title=state.lang==='ar'?topic.titleAr:topic.titleEn,steps=state.lang==='ar'?topic.stepsAr:topic.stepsEn;return `<article class="help-card"><h3>${esc(title)}</h3><ol>${steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><button type="button" class="secondary help-go" data-help-view="${topic.view}">${state.lang==='ar'?'اذهب إلى القسم':'Go to section'}</button></article>`}
function renderHelpResults_(query=''){const box=document.querySelector('#helpResults');if(!box)return;const rows=helpResults_(query);box.innerHTML=rows.length?rows.map(helpCard_).join(''):`<div class="empty">${state.lang==='ar'?'لم أجد نتيجة مطابقة. جرّب وصف المهمة بكلمات أخرى.':'No matching result. Try describing the task differently.'}</div>`}
function openHelp_(){const center=document.querySelector('#helpCenter');center?.classList.add('open');center?.setAttribute('aria-hidden','false');document.querySelector('#helpSearch')?.focus();renderHelpResults_('')}
function closeHelp_(){const center=document.querySelector('#helpCenter');center?.classList.remove('open');center?.setAttribute('aria-hidden','true');document.querySelector('#helpOpen')?.focus()}
let actionButton_=null,actionButtonDepth_=0;
function beginActionButton_(){const button=actionButton_;if(!button||!button.isConnected)return null;actionButtonDepth_++;button.classList.add('is-loading');button.disabled=true;button.setAttribute('aria-busy','true');return button}
function endActionButton_(button){if(!button)return;actionButtonDepth_=Math.max(0,actionButtonDepth_-1);if(actionButtonDepth_)return;button.classList.remove('is-loading');button.disabled=false;button.removeAttribute('aria-busy')}
document.addEventListener('click',event=>{const button=event.target.closest('button');actionButton_=button&&button.closest('#app')&&!button.closest('.nav,.topbar')?button:null},true);
document.addEventListener('submit',event=>{const button=event.submitter||event.target.querySelector('button[type="submit"],button:not([type])');if(button)actionButton_=button},true);
const pendingReads_=new Map();
let api=(action,payload={})=>{
  const readOnly=/^(app\.(bootstrap|freshness)|view\.load|profile|report\.|accounting\.|finance\.(dashboard|statements)|notification\.list|agreement\.list)/.test(action);
  const request={action,payload,sessionToken:sessionToken_()},key=JSON.stringify(request);
  if(readOnly&&pendingReads_.has(key))return pendingReads_.get(key);
  const busyButton=beginActionButton_();
  const send=()=>new Promise((resolve,reject)=>{
    let settled=false;const controller=new AbortController();
    const finish=(fn,value)=>{if(settled)return;settled=true;clearTimeout(timer);fn(value)};
    const timer=setTimeout(()=>{controller.abort();finish(reject,new Error(state.lang==='ar'?'الاتصال استغرق وقتًا أطول من المتوقع. بياناتك محفوظة؛ أعد المحاولة.':'The connection took too long. Your data is preserved; retry.'))},45000);
    if(isAppsScriptHost_()){google.script.run.withSuccessHandler(v=>finish(resolve,v)).withFailureHandler(e=>finish(reject,e)).apiCall(request);return}
    fetch(API_URL,{method:'POST',headers:{'Content-Type':'text/plain;charset=UTF-8'},body:JSON.stringify(request),credentials:'omit',redirect:'follow',cache:'no-store',signal:controller.signal})
      .then(response=>{if(!response.ok)throw new Error('HTTP '+response.status);return response.json()})
      .then(v=>finish(resolve,v)).catch(e=>finish(reject,e));
  });
  const result=(async()=>{try{try{return await send()}catch(error){if(!readOnly)throw error;await new Promise(r=>setTimeout(r,700));return await send()}}finally{endActionButton_(busyButton);pendingReads_.delete(key)}})();
  if(readOnly)pendingReads_.set(key,result);
  return result;
};
function loginView(message='',presetEmail=''){
  document.querySelector('#app').innerHTML=`<section class="splash"><form id="loginForm" class="brand panel"><div class="login-logo">${logo()}</div><p>${t('powered')}</p>${message?`<div class="notice error">${esc(message)}</div>`:''}<div id="loginNotice" role="status"></div><label class="field">${t('email')} ${state.lang==='ar'?'(اختياري)':'(optional)'}<input name="email" type="email" autocomplete="email" value="${esc(presetEmail)}"></label><p>${state.lang==='ar'?'اكتب بريدك أو اتركه فارغًا لاختيار حسابك عند Google. لو الحساب مش موجود، اختر «استخدام حساب آخر».':'Enter your email or leave it blank to choose your Google account. Select “Use another account” if it is not listed.'}</p><button type="button" class="primary" id="googleLogin" disabled>${state.lang==='ar'?'الدخول بحساب Google':'Sign in with Google'}</button></form></section>`;
  const form=document.querySelector('#loginForm');
  form.onsubmit=event=>{event.preventDefault();document.querySelector('#googleLogin')?.click()};
  mountGoogleLogin_();
}
function foozixLoader_(compact=false){return `<div class="foozix-loader ${compact?'compact':''}" role="status" aria-label="Loading"><div class="foozix-orbit"><span>F</span><span>O</span><span>O</span><span>Z</span><span>I</span><span>X</span></div><small class="loading-copy">Loading</small></div>`}
function splash(){document.querySelector('#app').innerHTML=`<section class="splash"><div class="brand">${logo()}<p>${t('powered')}</p>${foozixLoader_()}</div></section>`}
function canAction(module,action='view'){if(state.profile.role==='SUPER_ADMIN')return true;const actions=(state.profile.permissions&&state.profile.permissions[module])||[];return actions.includes(action)||actions.includes('*')}
function allowed(k){const m={dashboard:'dashboard',tasks:'approvals',transaction:'transactions',projects:'projects',clients:'clients',parties:'parties',reports:'finance',finance:'finance',employees:'employees',loans:'loans',assets:'assets',audit:'audit',settings:'settings'};return (k==='tasks'&&canAction('transactions','create'))||canAction(m[k],'view')||canAction(m[k],'create')}
function syncMobileMode(){const mobile=/Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent)||matchMedia('(pointer:coarse)').matches||screen.width<=850;document.documentElement.classList.toggle('mobile-ui',mobile);if(!mobile)state.sidebarOpen=false}
function setSidebar(open){state.sidebarOpen=!!open;document.querySelector('.sidebar')?.classList.toggle('open',state.sidebarOpen);document.querySelector('.sidebar-backdrop')?.classList.toggle('show',state.sidebarOpen);document.querySelector('#menuToggle')?.setAttribute('aria-expanded',String(state.sidebarOpen))}
function render(){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';const menu=nav.filter(allowed).map(k=>`<button data-view="${k}" class="${state.view===k?'active':''} ${k==='settings'?'nav-settings':''}">${navIcon(k)}<span>${t(k)}</span></button>`).join('');document.querySelector('#app').innerHTML=`<div class="layout"><button class="sidebar-backdrop" aria-label="${state.lang==='ar'?'إغلاق القائمة':'Close menu'}"></button><aside class="sidebar ${state.sidebarOpen?'open':''}"><div class="sidebar-brand">${logo()}<small>FOOZIX Live</small></div><nav class="nav">${menu}</nav></aside><main class="main"><header class="topbar"><button id="menuToggle" class="menu-toggle" aria-label="${state.lang==='ar'?'فتح القائمة':'Close menu'}" aria-expanded="${state.sidebarOpen}">☰</button><span class="welcome">${t('hello')}، ${esc(state.lang==='ar'?(state.profile.nameAr||state.profile.nameEn):(state.profile.nameEn||state.profile.nameAr))}<small>${esc(state.profile.email||'')}</small></span><button id="helpOpen" class="help-button" type="button" aria-label="${state.lang==='ar'?'مساعدة ودليل الاستخدام':'Help and user manual'}" title="${state.lang==='ar'?'مساعدة ودليل الاستخدام':'Help and user manual'}">؟</button><button id="lang" class="language">${t('language')}</button><button id="logout" class="language">${state.lang==='ar'?'تسجيل الخروج / تبديل الحساب':'Sign out / Switch account'}</button></header><section class="content">${state.loading?`<div class="view-loading">${foozixLoader_(true)}</div>`:''}${state.notice?`<div class="notice ${state.notice.type}">${esc(state.notice.text)}</div>`:''}${view()}</section></main></div><aside id="helpCenter" class="help-center" aria-hidden="true"><div class="help-head"><div><h2>${state.lang==='ar'?'مركز مساعدة FOOZIX':'FOOZIX Help Center'}</h2><small>${state.lang==='ar'?'اكتب ما تريد عمله بأي صياغة':'Describe what you want in your own words'}</small></div><button id="helpClose" type="button" aria-label="${state.lang==='ar'?'إغلاق':'Close'}">×</button></div><label class="help-search"><span>⌕</span><input id="helpSearch" type="search" autocomplete="off" placeholder="${state.lang==='ar'?'مثال: عايز أطبع مشروع أو أسجل فلوس داخلة':'Example: print a project or record money received'}"></label><div class="help-suggestions"><button type="button" data-help-query="${state.lang==='ar'?'اطبع كشف مشروع':'print project statement'}">${state.lang==='ar'?'طباعة كشف مشروع':'Print project statement'}</button><button type="button" data-help-query="${state.lang==='ar'?'سجل دفعة':'record payment'}">${state.lang==='ar'?'تسجيل دفعة':'Record payment'}</button><button type="button" data-help-query="${state.lang==='ar'?'عدل اسم عميل':'edit client name'}">${state.lang==='ar'?'تعديل عميل':'Edit client'}</button></div><div id="helpResults" class="help-results"></div></aside><button id="helpShade" class="help-shade" aria-label="${state.lang==='ar'?'إغلاق المساعدة':'Close help'}"></button>`;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>openView(b.dataset.view));document.querySelector('#menuToggle').onclick=()=>setSidebar(!state.sidebarOpen);document.querySelector('.sidebar-backdrop').onclick=()=>setSidebar(false);document.querySelector('#helpOpen').onclick=openHelp_;document.querySelector('#helpClose').onclick=closeHelp_;document.querySelector('#helpShade').onclick=closeHelp_;document.querySelector('#helpSearch').oninput=e=>renderHelpResults_(e.target.value);document.querySelectorAll('[data-help-query]').forEach(b=>b.onclick=()=>{const input=document.querySelector('#helpSearch');input.value=b.dataset.helpQuery;renderHelpResults_(input.value)});document.querySelector('#helpCenter').onclick=e=>{const go=e.target.closest('[data-help-view]');if(!go)return;closeHelp_();openView(go.dataset.helpView)};document.querySelector('#lang').onclick=()=>{state.lang=state.lang==='ar'?'en':'ar';localStorage.setItem('foozix.lang',state.lang);render()};document.querySelector('#logout').onclick=()=>{const email=state.profile?.email||'';clearSessionToken_();state.profile=null;state.data={};state.loadedAt={};loginView('',email)};wire()}
function viewFresh(view){return Number(state.loadedAt[view]||0)>0}
async function openView(next){if(next===state.view){setSidebar(false);return}state.view=next;state.notice=null;state.sidebarOpen=false;if(Date.now()-Number(state.loadedAt[next]||0)<300000){state.loading=false;render();return}state.loading=true;render();try{await load();state.loadedAt[next]=Date.now()}catch(error){state.notice={type:'error',text:error.message||String(error)}}finally{state.loading=false;render()}}
function view(){if(state.view==='dashboard')return dash();if(state.view==='transaction')return txFormSmart();if(meta[state.view])return masterSmart(state.view);if(state.view==='employees')return employeesSmart();if(state.view==='loans')return loansSmart();if(state.view==='tasks')return approvals();if(state.view==='reports')return reports();if(state.view==='finance')return financeSmart();if(state.view==='assets')return assets();if(state.view==='audit')return auditView();if(state.view==='settings')return settings();return `<h1>${t(state.view)}</h1>${table(state.data[state.view]||[])}`}
function assets(){const items=state.data.assets||[],history=state.data.historicalAssetMovements||[];return `<h1>${t('assets')}</h1><div class="panel"><p>${state.lang==='ar'?'سجل الأصول الحالية والمشتريات التاريخية المرحلة.':'Current asset register and migrated historical asset purchases.'}</p></div>${items.length?table(items):history.length?table(history):`<div class="panel empty">${t('none')}</div>`}`}
function auditView(){const items=state.data.audit||[];return `<h1>${t('audit')}</h1><div class="panel"><div class="form-grid"><label class="field">${state.lang==='ar'?'من تاريخ':'From date'}<input id="auditFrom" type="date"></label><label class="field">${state.lang==='ar'?'إلى تاريخ':'To date'}<input id="auditTo" type="date"></label></div><div class="actions"><button id="filterAudit" class="primary">${state.lang==='ar'?'تطبيق':'Apply'}</button><button id="printAudit" class="secondary">PDF / ${state.lang==='ar'?'طباعة':'Print'}</button></div></div><div id="auditOutput" class="formal-report">${reportHeader_(state.lang==='ar'?'سجل المراجعة':'Audit log','')}${table(items)}</div>`}
function settings(){const backups=state.data.backups||[],a=state.data.automationStatus||{},b=a.backup||{},al=a.alerts||{};const status=x=>x?state.lang==='ar'?'مفعّل':'Enabled':state.lang==='ar'?'متوقف':'Disabled';return `<h1>${t('settings')}</h1><div class="grid"><article class="card"><b>${state.lang==='ar'?'النسخ الاحتياطي التلقائي':'Automatic backup'}</b><strong>${status(b.enabled)}</strong><small>${state.lang==='ar'?'الجدول':'Schedule'}: ${esc(b.schedule||'02:00')} — ${state.lang==='ar'?'آخر تشغيل':'Last run'}: ${esc(b.lastRun||'—')} ${esc(b.lastStatus||'')}</small></article><article class="card"><b>${state.lang==='ar'?'فحص التنبيهات':'Alert checks'}</b><strong>${status(al.enabled)}</strong><small>${state.lang==='ar'?'الجدول':'Schedule'}: ${esc(al.schedule||'EVERY_HOUR')} — ${state.lang==='ar'?'آخر تشغيل':'Last run'}: ${esc(al.lastRun||'—')}</small></article></div><div class="panel"><div class="actions"><button id="driveSetup" class="primary">${state.lang==='ar'?'تهيئة مجلدات المستندات':'Set up document folders'}</button><button id="backupNow" class="primary">${state.lang==='ar'?'إنشاء نسخة احتياطية الآن':'Create backup now'}</button><button id="backupSchedule" class="secondary">${state.lang==='ar'?'تفعيل النسخ اليومي الساعة 2 صباحًا':'Enable daily backup at 2 AM'}</button><button id="backupDisable" class="secondary">${state.lang==='ar'?'إيقاف النسخ اليومي':'Disable daily backup'}</button><button id="alertSchedule" class="secondary">${state.lang==='ar'?'تفعيل فحص التنبيهات كل ساعة':'Enable hourly alert checks'}</button><button id="alertDisable" class="secondary">${state.lang==='ar'?'إيقاف فحص التنبيهات':'Disable alert checks'}</button></div></div><div class="panel"><h2>${state.lang==='ar'?'استعادة نسخة احتياطية':'Restore a backup'}</h2><p>${state.lang==='ar'?'الاستعادة تنشئ نسخة أمان تلقائيًا أولًا، وهي متاحة للمالك التقني فقط.':'A safety backup is created automatically first. Only the technical owner can restore.'}</p><div class="form-grid"><label class="field">${state.lang==='ar'?'معرف النسخة':'Backup ID'}<select id="restoreBackupId"><option value=""></option>${backups.filter(x=>x['الحالة']==='SUCCESS').map(x=>`<option value="${esc(x['معرف النسخة'])}">${esc(x['بدأ في'])} — ${esc(x['معرف النسخة'])}</option>`).join('')}</select></label><label class="field">${state.lang==='ar'?'اكتب RESTORE للتأكيد':'Type RESTORE to confirm'}<input id="restoreConfirm"></label></div><button id="restoreBackup" class="secondary">${state.lang==='ar'?'استعادة النسخة المحددة':'Restore selected backup'}</button></div>${table(backups)}`}
function projectSummaryTable_(projects){if(!projects.length)return `<div class="empty">${t('none')}</div>`;return `<div class="table-wrap project-summary-table"><table><thead><tr><th>${state.lang==='ar'?'المشروع':'Project'}</th><th>${state.lang==='ar'?'إجمالي قيمة العميل':'Client total'}</th><th>${state.lang==='ar'?'إجمالي ما دفعه العميل':'Client paid'}</th><th>${state.lang==='ar'?'مصروفات المشروع فقط':'Project expenses only'}</th><th>${state.lang==='ar'?'إجمالي النسبة المستحقة':'Due markup'}</th><th>${state.lang==='ar'?'رصيد دفعات العميل المتاح':'Available client funds'}</th><th>${state.lang==='ar'?'المتبقي المطلوب من العميل':'Outstanding from client'}</th></tr></thead><tbody>${projects.map(p=>`<tr><td class="project-name">${esc(p['الاسم العربي']||p['الاسم الإنجليزي']||p['معرف المشروع'])}</td><td>${money(p.clientValue)}</td><td>${money(p.receipts)}</td><td>${money(p.expenses)}</td><td>${money(p.percentageDue)}</td><td>${money(p.availableClientFunds)}</td><td>${money(p.outstanding)}</td></tr>`).join('')}</tbody></table></div>`}
function financialProjectDashboard_(){const s=state.data.projectFinancialSummary;if(!s)return '';const x=s.totals,n=s.active.length,scope=state.lang==='ar'?`على ${n} مشروعًا جاريًا`:`Across ${n} active projects`;return `<h2 class="financial-dashboard-title">${state.lang==='ar'?'الملخص المالي للمشروعات الجارية':'Active projects financial summary'} <small>(${scope})</small></h2><div class="grid"><article class="card">${state.lang==='ar'?'إجمالي الأعمال المستحقة':'Total billed work'}<small>${scope}</small><strong>${money(x.clientValue)}</strong></article><article class="card">${state.lang==='ar'?'إجمالي ما دفعه العملاء':'Client payments'}<small>${scope}</small><strong>${money(x.receipts)}</strong></article><article class="card">${state.lang==='ar'?'مصروفات المشروعات فقط':'Project expenses only'}<small>${scope}</small><strong>${money(x.expenses)}</strong></article><article class="card">${state.lang==='ar'?'إجمالي النسبة المستحقة':'Total due markup'}<small>${scope}</small><strong>${money(x.percentageDue)}</strong></article><article class="card">${state.lang==='ar'?'النسبة المحصلة':'Collected markup'}<small>${scope}</small><strong>${money(x.markupCollected)}</strong></article><article class="card">${state.lang==='ar'?'النسبة غير المحصلة':'Uncollected markup'}<small>${scope}</small><strong>${money(x.markupOutstanding)}</strong></article><article class="card">${state.lang==='ar'?'رصيد دفعات العملاء المتاح':'Available client funds'}<small>${scope}</small><strong>${money(x.availableClientFunds)}</strong></article><article class="card">${state.lang==='ar'?'المتبقي المطلوب من العملاء':'Outstanding from clients'}<small>${scope}</small><strong>${money(x.outstanding)}</strong></article></div><div class="panel"><h2>${state.lang==='ar'?'المشروعات الجارية':'Active projects'}</h2>${projectSummaryTable_(s.active)}</div><details class="panel archive-projects"><summary>${state.lang==='ar'?'أرشيف المشروعات':'Project archive'} (${s.archived.length})</summary>${projectSummaryTable_(s.archived)}</details>`}
function dash(){const alerts=state.data.alerts||[];return `<h1>${t('dashboard')}</h1><div class="grid"><article class="card">${t('tasks')}<strong>${(state.data.tasks||[]).length}</strong></article><article class="card">${t('projects')}<strong>${(state.data.projects||[]).length}</strong></article><article class="card">${t('employees')}<strong>${(state.data.employees||[]).length}</strong></article><article class="card">${state.lang==='ar'?'التنبيهات المفتوحة':'Open alerts'}<strong>${alerts.length}</strong></article></div>${financialProjectDashboard_()}${alerts.length?`<div class="panel">${alerts.slice(0,10).map(a=>`<p><b>${esc(a['مستوى الخطورة'])}</b> — ${esc(state.lang==='ar'?a['الرسالة العربية']:a['الرسالة الإنجليزية'])}</p>`).join('')}</div>`:''}`}
function txForm(){const allTypes=[['PROJECT_EXPENSE','مصروف مشروع','Project expense'],['CUSTOMER_RECEIPT','تحصيل عميل','Customer receipt'],['SUPPLIER_PAYMENT','دفع مورد/مقاول','Supplier payment'],['INTERNAL_TRANSFER','تحويل داخلي','Internal transfer'],['EMPLOYEE_LOAN','سلفة موظف','Employee loan'],['EMPLOYEE_LOAN_REPAYMENT','سداد سلفة','Loan repayment'],['PAYROLL_PAYMENT','دفع رواتب','Payroll payment'],['PARTNER_WITHDRAWAL','مسحوبات شريك','Partner withdrawal'],['PARTNER_DEPOSIT','إيداع شريك','Partner deposit'],['OPERATING_EXPENSE','مصروف تشغيلي','Operating expense'],['BANK_FEE','رسوم بنكية','Bank fee'],['FIXED_ASSET_PURCHASE','شراء أصل ثابت','Fixed asset purchase']];const modules={PROJECT_EXPENSE:'transactions',CUSTOMER_RECEIPT:'transactions',SUPPLIER_PAYMENT:'transactions',INTERNAL_TRANSFER:'transactions',EMPLOYEE_LOAN:'loans',EMPLOYEE_LOAN_REPAYMENT:'loans',PAYROLL_PAYMENT:'payroll',PARTNER_WITHDRAWAL:'finance',PARTNER_DEPOSIT:'finance',OPERATING_EXPENSE:'transactions',BANK_FEE:'finance',FIXED_ASSET_PURCHASE:'assets'};const types=allTypes.filter(x=>canAction(modules[x[0]],'create'));return `<h1>${t('transaction')}</h1><form id="tx" class="panel"><div class="form-grid"><label class="field">${t('type')}<select name="type" required>${types.map(x=>`<option value="${x[0]}">${state.lang==='ar'?x[1]:x[2]}</option>`).join('')}</select></label><label class="field">${t('date')}<input name="transactionDate" type="date" required></label><label class="field">${t('amount')}<input name="amount" type="number" min=".01" step=".01" required></label><label class="field">${t('currency')}<input name="currency" value="EGP"></label><label class="field">${state.lang==='ar'?'سعر الصرف':'Exchange rate'}<input name="exchangeRate" type="number" min=".000001" step=".000001" value="1"></label>${select('projectId',t('project'),state.data.projects||[],'معرف المشروع')}${select('clientId',t('client'),state.data.clients||[],'معرف العميل')}${select('partyId',state.lang==='ar'?'المورد أو المقاول':'Supplier or contractor',state.data.parties||[],'معرف الطرف')}${select('employeeId',t('employee'),state.data.employees||[],'معرف الموظف')}${select('finishItemId',state.lang==='ar'?'بند التشطيب':'Finishing item',state.data.finishItems||[],'معرف البند')}${select('sourceAccountId',state.lang==='ar'?'حساب المصدر':'Source account',state.data.cashAccounts||[],'معرف الحساب النقدي')}${select('targetAccountId',state.lang==='ar'?'حساب المستلم':'Target account',state.data.cashAccounts||[],'معرف الحساب النقدي')}<label class="field">${t('description')}<input name="description" required></label><label class="field">${state.lang==='ar'?'الكمية':'Quantity'}<input name="quantity" type="number" min="0" step=".01"></label><label class="field">${state.lang==='ar'?'الوحدة':'Unit'}<input name="unit"></label><label class="field">${t('payment')}<select name="paymentMethod"><option value="CASH">${state.lang==='ar'?'نقدي':'Cash'}</option><option value="BANK_TRANSFER">${state.lang==='ar'?'تحويل بنكي':'Bank transfer'}</option><option value="CHEQUE">${state.lang==='ar'?'شيك':'Cheque'}</option></select></label><label class="field">${t('reference')}<input name="reference"></label><label class="field">${state.lang==='ar'?'إثبات التحويل أو العملية':'Transfer or transaction evidence'}<input id="evidence" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"><input name="documentId" type="hidden"></label><label class="field">${state.lang==='ar'?'تأكيد مسؤولية التسجيل دون إثبات نقدي':'Confirm responsibility for cash entry without evidence'}<input name="noEvidenceConfirmation" type="checkbox"></label><label class="field">${state.lang==='ar'?'نسبة خاصة للبند % — اتركها فارغة لاستخدام نسبة المشروع':'Item override % — leave blank to use project default'}<input name="markupRate" type="number" min="0" max="100" step=".01" placeholder="${state.lang==='ar'?'نسبة المشروع الافتراضية':'Project default'}"></label><label class="field">${state.lang==='ar'?'تحميل على العميل':'Charge client'}<input name="chargeClient" type="checkbox"></label><label class="field">${state.lang==='ar'?'تتحمله الشركة':'Company bears cost'}<input name="companyBears" type="checkbox"></label><label class="field">${t('notes')}<textarea name="notes"></textarea></label><label class="field">${state.lang==='ar'?'تأكيد إنشاء حركة جديدة رغم التطابق':'Confirm new transaction despite match'}<input name="confirmDuplicate" type="checkbox"></label></div><button class="primary">${t('submit')}</button></form>`}
function master(k){const m=meta[k],items=state.data[k]||[];return `<h1>${t(k)}</h1><form id="master" data-entity="${m.entity}" class="panel"><div class="form-grid">${k==='projects'?select('معرف العميل',t('client'),state.data.clients||[],'معرف العميل')+`<label class="field">${state.lang==='ar'?'النسبة العامة للمشروع %':'Default project markup %'}<input name="النسبة العامة" type="number" min="0" max="100" step=".01" required></label><label class="field">${state.lang==='ar'?'قيمة التصميم':'Design value'}<input name="قيمة التصميم" type="number" min="0" step=".01"></label><label class="field">${state.lang==='ar'?'قيمة العقد':'Contract value'}<input name="قيمة العقد" type="number" min="0" step=".01"></label>`:''}<label class="field">${t('nameAr')}<input name="الاسم العربي" required></label><label class="field">${t('nameEn')}<input name="الاسم الإنجليزي"></label><label class="field">${t('phone')}<input name="الهاتف"></label><label class="field">${t('email')}<input name="البريد" type="email"></label><label class="field">${t('address')}<input name="العنوان"></label></div><button class="primary">${t('add')}</button></form>${table(items)}`}
function employees(){const cycles=state.data.payrollCycles||[],cycle=cycles[0],details=state.data.payrollDetails||[],people=state.data.employees||[];return `<h1>${t('employees')}</h1><form id="employeeForm" class="panel"><h2>${state.lang==='ar'?'إضافة موظف':'Add employee'}</h2><div class="form-grid"><label class="field">${t('nameAr')}<input name="الاسم العربي" required></label><label class="field">${t('nameEn')}<input name="الاسم الإنجليزي"></label><label class="field">${t('email')}<input name="البريد" type="email"></label><label class="field">${t('phone')}<input name="الهاتف"></label><label class="field">${state.lang==='ar'?'الوظيفة':'Job title'}<input name="الوظيفة"></label><label class="field">${state.lang==='ar'?'الراتب الأساسي':'Base salary'}<input name="الراتب الأساسي" type="number" min="0" step=".01"></label><label class="field">${state.lang==='ar'?'تاريخ التعيين':'Hire date'}<input name="تاريخ التعيين" type="date"></label><label class="field">${t('role')}<select name="role"><option value="SITE_ENGINEER">مهندس موقع — Site Engineer</option><option value="HR_ADMIN">مسؤول إداري — HR Admin</option><option value="MANAGER">مدير — Manager</option></select></label><label class="field">${state.lang==='ar'?'السماح بالدخول':'Allow login'}<input name="السماح بالدخول" type="checkbox"></label></div><div class="actions"><button class="primary">${t('add')}</button><button id="payroll" type="button" class="secondary">${t('openPayroll')}</button></div></form><form id="employeeChange" class="panel"><h2>${state.lang==='ar'?'زيادة مرتب أو ترقية':'Salary increase or promotion'}</h2><div class="form-grid">${select('employeeId',t('employee'),people,'معرف الموظف')}<label class="field">${state.lang==='ar'?'نوع التغيير':'Change type'}<select name="changeType"><option value="SALARY">${state.lang==='ar'?'تعديل راتب':'Salary change'}</option><option value="PROMOTION">${state.lang==='ar'?'ترقية':'Promotion'}</option></select></label><label class="field">${state.lang==='ar'?'القيمة الجديدة':'New value'}<input name="newValue" required></label><label class="field">${state.lang==='ar'?'تاريخ السريان':'Effective date'}<input name="effectiveDate" type="date" required></label><label class="field">${t('notes')}<input name="reason"></label></div><button class="primary">${t('submit')}</button></form>${cycle?payrollPanel(cycle,details,people):''}${table(people)}`}
function payrollPanel(cycle,details,people){const pending=details.find(x=>x['حالة الموظف']!=='COMPLETED')||details[0];const person=pending&&people.find(x=>x['معرف الموظف']===pending['معرف الموظف']);return `<div class="panel"><h2>${state.lang==='ar'?'مرتبات':'Payroll'} ${cycle['السنة']}/${cycle['الشهر']} — ${esc(cycle['الحالة'])}</h2>${pending?`<form id="payrollDetail"><input type="hidden" name="id" value="${esc(pending['معرف تفصيل الراتب'])}"><input type="hidden" name="version" value="${esc(pending['الإصدار'])}"><input type="hidden" name="baseSalary" value="${esc(pending['الراتب الأساسي'])}"><p><b>${esc(state.lang==='ar'?(person&&person['الاسم العربي']):(person&&person['الاسم الإنجليزي']))}</b> — ${state.lang==='ar'?'الراتب الأساسي':'Base salary'}: ${esc(pending['الراتب الأساسي'])}</p><div class="form-grid"><label class="field">${state.lang==='ar'?'أيام العمل':'Work days'}<input name="workDays" type="number" min="0" required></label><label class="field">${state.lang==='ar'?'أيام الغياب':'Absence days'}<input name="absenceDays" type="number" min="0" value="0"></label><label class="field">${state.lang==='ar'?'ساعات الإضافي':'Overtime hours'}<input name="overtimeHours" type="number" min="0" value="0"></label><label class="field">${state.lang==='ar'?'قيمة الإضافي':'Overtime value'}<input name="overtimeValue" type="number" min="0" value="0"></label><label class="field">${state.lang==='ar'?'البدلات':'Allowances'}<input name="allowances" type="number" value="0"></label><label class="field">${state.lang==='ar'?'المكافآت':'Bonuses'}<input name="bonuses" type="number" value="0"></label><label class="field">${state.lang==='ar'?'الخصومات':'Deductions'}<input name="deductions" type="number" value="0"></label><label class="field">${state.lang==='ar'?'قسط السلفة':'Loan installment'}<input name="loanInstallment" type="number" value="${esc(pending['قسط السلفة المقترح']||0)}"></label><label class="field">${state.lang==='ar'?'تأكيد اكتمال الموظف':'Employee checkpoint'}<input name="complete" type="checkbox"></label></div><button class="primary">${t('save')}</button></form>`:`<p>${state.lang==='ar'?'اكتملت بيانات جميع الموظفين.':'All employee details are complete.'}</p>`}<div class="actions"><button id="submitPayroll" class="primary" data-id="${esc(cycle['معرف الدورة'])}" data-version="${esc(cycle['الإصدار']||0)}">${state.lang==='ar'?'إتمام وإرسال المرتبات للمراجعة':'Submit payroll for review'}</button><button id="lockPayroll" class="secondary" data-id="${esc(cycle['معرف الدورة'])}" data-version="${esc(cycle['الإصدار']||0)}">${state.lang==='ar'?'الإقفال النهائي':'Final lock'}</button></div></div>`}
function loans(){return `<h1>${t('loans')}</h1><form id="loanForm" class="panel"><div class="form-grid">${select('employeeId',t('employee'),state.data.employees||[],'معرف الموظف')}<label class="field">${t('date')}<input name="date" type="date" required></label><label class="field">${t('amount')}<input name="amount" type="number" min=".01" step=".01" required></label><label class="field">${t('notes')}<input name="overrideReason"></label></div><button class="primary">${t('submit')}</button></form>${table(state.data.loans||[])}`}
function approvals(){const a=state.data.tasks||[];return `<h1>${t('tasks')}</h1>${a.length?a.map(x=>`<article class="panel"><b>${esc(x['الوحدة'])} — ${esc(x['نوع الإجراء'])}</b><p>${esc(x['السبب']||'')}</p><div class="actions"><button class="primary decision" data-id="${x['معرف الموافقة']}" data-value="APPROVE">${t('approve')}</button><button class="secondary decision" data-id="${x['معرف الموافقة']}" data-value="REJECT">${t('reject')}</button></div></article>`).join(''):`<div class="panel empty">${t('none')}</div>`}`}
function reports(){const r=state.data.projectReport,selected=String(state.data.reportProjectId||''),projects=state.data.projects||[];return `<h1>${t('reports')}</h1><div class="panel"><div class="form-grid"><label class="field">${t('project')}<select name="reportProject"><option value=""></option>${projects.map(x=>`<option value="${esc(x['معرف المشروع'])}" ${String(x['معرف المشروع'])===selected?'selected':''}>${esc(x['الاسم العربي']||x['الاسم الإنجليزي']||x['معرف المشروع'])}</option>`).join('')}</select></label></div><div class="actions"><button id="summaryReport" class="primary">${state.lang==='ar'?'الفاتورة المجمعة':'Summary invoice'}</button><button id="detailReport" class="secondary">${state.lang==='ar'?'كشف الحساب التفصيلي':'Detailed statement'}</button><button id="printReport" class="secondary">PDF / ${state.lang==='ar'?'طباعة':'Print'}</button></div></div>${r?reportOutput(r):''}`}
function reportHeader_(title,subtitle){return `<header class="report-head"><div class="report-logo">${logo()}</div><div><h1>${title}</h1><p>${subtitle||'Arte Divino · FOOZIX Live'}</p></div></header>`}
function reportParty_(r){const p=r.project||{},c=r.client||{},ar=state.lang==='ar',clientName=ar?(c['الاسم العربي']||c['الاسم الإنجليزي']):(c['الاسم الإنجليزي']||c['الاسم العربي']),projectName=ar?(p['الاسم العربي']||p['الاسم الإنجليزي']):(p['الاسم الإنجليزي']||p['الاسم العربي']);return `<section class="report-party report-identity"><article class="report-identity-card"><span class="report-identity-label">${ar?'العميل':'Client'}</span><div class="report-identity-title"><h3>${esc(clientName||'—')}</h3><span class="report-code">${ar?'كود العميل':'Client code'}: ${esc(c['كود العميل']||'—')}</span></div><div class="report-identity-meta"><span><b>${ar?'الهاتف':'Phone'}:</b> ${esc(c['الهاتف']||'—')}</span><span><b>${ar?'العنوان':'Address'}:</b> ${esc(c['العنوان']||'—')}</span></div></article><article class="report-identity-card"><span class="report-identity-label">${ar?'المشروع':'Project'}</span><div class="report-identity-title"><h3>${esc(projectName||'—')}</h3><span class="report-code">${ar?'كود المشروع':'Project code'}: ${esc(p['كود المشروع']||'—')}</span></div><div class="report-identity-meta"><span><b>${ar?'موقع المشروع':'Project location'}:</b> ${esc(p['العنوان']||'—')}</span></div></article>${r.contractValue!==null&&Number(r.contractValue)>0?`<div class="report-contract"><b>${ar?'قيمة العقد':'Contract value'}:</b> ${money(r.contractValue)}</div>`:''}</section>`}
function invoiceTable_(rows){return `<div class="report-table"><table><thead><tr><th>${state.lang==='ar'?'البند':'Item'}</th><th>${state.lang==='ar'?'عدد الحركات':'Entries'}</th><th>${state.lang==='ar'?'قيمة الأعمال':'Work value'}</th><th>${state.lang==='ar'?'قيمة النسبة':'Markup value'}</th><th>${state.lang==='ar'?'قيمة العميل':'Client value'}</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.nameAr)}${x.companyBears?`<small class="company-tag">${state.lang==='ar'?'على حساب الشركة':'Company account'}</small>`:''}</td><td>${esc(x.count)}</td><td>${x.companyBears?'0.00':money(x.amount)}</td><td>${x.companyBears?'0.00':money(x.percentageValue)}</td><td>${x.companyBears?'0.00':money(x.clientValue)}</td></tr>`).join('')}</tbody></table></div>`}
function detailTable_(r){const rows=r.statement||[],special=r.hasSpecialRates,hasNotes=rows.some(x=>String(x.notes||'').trim());return `<div class="report-table"><table><thead><tr><th>${state.lang==='ar'?'التاريخ':'Date'}</th><th>${state.lang==='ar'?'البند والبيان':'Item & description'}</th><th>${state.lang==='ar'?'الطرف':'Party'}</th>${hasNotes?`<th>${state.lang==='ar'?'الملاحظات':'Notes'}</th>`:''}<th>${state.lang==='ar'?'القيمة':'Amount'}</th>${special?`<th>${state.lang==='ar'?'النسبة الخاصة':'Special rate'}</th>`:''}<th>${state.lang==='ar'?'قيمة النسبة':'Markup value'}</th><th>${state.lang==='ar'?'قيمة العميل':'Client value'}</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(formatDateValue_(x.transactionDate))}</td><td><b>${esc(x.finishItem||'')}</b><br><small>${esc(x.description||'')}${x.companyBears?` · ${state.lang==='ar'?'على حساب الشركة':'Company account'}`:''}</small></td><td>${esc(x.party||'—')}</td>${hasNotes?`<td>${esc(x.notes||'—')}</td>`:''}<td>${x.type==='CUSTOMER_RECEIPT'?money(x.receipt):money(x.amount)}</td>${special?`<td>${['TRANSACTION_OVERRIDE','PROJECT_ITEM'].includes(String(x.rateSource))?(Number(x.rate||0)*100).toFixed(2)+'%':'—'}</td>`:''}<td>${x.companyBears?'0.00':money(x.percentageValue)}</td><td>${x.companyBears?'0.00':money(x.clientValue)}</td></tr>`).join('')}</tbody></table></div>`}
function reportOutput(r){const detail=state.data.reportMode==='detail',base=(Number(r.baseRate||0)*100).toFixed(2)+'%',title=detail?(state.lang==='ar'?'كشف حساب المشروع التفصيلي':'Detailed project statement'):(state.lang==='ar'?'فاتورة العميل - ملخص المشروع':'Client invoice - project summary'),balanceLabel=Number(r.remaining)>=0?(state.lang==='ar'?'المتبقي على العميل':'Client balance due'):(state.lang==='ar'?'رصيد زائد للعميل':'Client credit');return `<div id="reportOutput" class="formal-report">${reportHeader_(title,(state.lang==='ar'?'حتى تاريخ ':'As of ')+esc(r.asOfDate||''))}${reportParty_(r)}${designSummary_(r)}<div class="report-rate"><span>${state.lang==='ar'?'نسبة المشروع الأساسية':'Base project rate'}</span><strong>${esc(base)}</strong></div>${detail?`<div class="grid report-totals"><article class="card">${state.lang==='ar'?'إجمالي المصروفات حتى الآن':'Expenses to date'}<strong>${money(r.expenses)}</strong></article><article class="card">${state.lang==='ar'?'إجمالي قيمة النسبة المستحقة حتى الآن':'Total markup due to date'}<strong>${money(r.percentageDue)}</strong></article><article class="card">${state.lang==='ar'?'إجمالي دفعات العميل':'Client payments'}<strong>${money(r.receipts)}</strong></article><article class="card">${state.lang==='ar'?'الرصيد المتاح':'Available balance'}<strong>${money(r.availableBalance)}</strong></article></div>${detailTable_(r)}`:`${invoiceTable_(r.summary||[])}<div class="report-summary"><div><span>${state.lang==='ar'?'إجمالي قيمة الأعمال':'Total work value'}</span><strong>${money(r.workCost)}</strong></div>${Number(r.designValue||0)?`<div><span>${state.lang==='ar'?'قيمة التصميم - منفصلة عن النسبة':'Design value - excluded from markup'}</span><strong>${money(r.designValue)}</strong></div>`:''}<div><span>${state.lang==='ar'?'قيمة النسبة':'Markup value'}</span><strong>${money(r.invoiceMarkup)}</strong></div><div class="grand"><span>${state.lang==='ar'?'إجمالي المستحق':'Total due'}</span><strong>${money(r.total)}</strong></div><div><span>${state.lang==='ar'?'إجمالي المدفوع':'Total paid'}</span><strong>${money(r.receipts)}</strong></div><div class="grand"><span>${balanceLabel}</span><strong>${money(Math.abs(Number(r.remaining||0)))}</strong></div></div>`}<div class="report-note">${state.lang==='ar'?'أي نسبة خاصة تستبدل نسبة المشروع الأساسية على البند المحدد فقط. البنود التي تتحملها الشركة تظهر فقط دون إدراج قيمتها ضمن حسابات العميل.':'Any special rate replaces the base project rate for that item only. Company-account items are shown without inclusion in client calculations.'}</div><footer class="report-footer">${state.lang==='ar'?'صادر من نظام FOOZIX Live لشركة Arte Divino':'Generated by FOOZIX Live for Arte Divino'} · ${esc(String(r.generatedAt||'').slice(0,19))}</footer></div>`}
function liquidityGuard_(){const summary=state.data.projectFinancialSummary,closed=new Set(['FINANCIALLY_CLOSED','CLOSED','مغلق']),active=(summary?.active||[]).filter(p=>!closed.has(String(p['الحالة المالية']||'').trim().toUpperCase())),clientReserve=active.reduce((sum,p)=>sum+Math.max(0,Number(p.availableClientFunds||0)),0),agreements=state.data.agreements||[],vendorReserve=agreements.filter(a=>String(a['الحالة']||'ACTIVE')==='ACTIVE').reduce((sum,a)=>sum+Math.max(0,Number(a['القيمة المعدلة']||a['القيمة الأصلية']||0)-Number(a['قيمة الأعمال المعتمدة']||0)),0),employees=(state.data.employees||[]).filter(e=>String(e['الحالة']||'Active').toUpperCase()==='ACTIVE'&&String(e['كود الموظف']||'')!=='FOOZIX-OWNER'),basePayroll=employees.reduce((sum,e)=>sum+Number(e['الراتب الأساسي']||0),0),cyclePayroll=(state.data.payrollDetails||[]).reduce((sum,p)=>sum+Number(p['الصافي']||0),0),payrollReserve=Math.max(basePayroll,cyclePayroll),rentReserve=18700,total=clientReserve+vendorReserve+payrollReserve+rentReserve;return {clientReserve,vendorReserve,payrollReserve,rentReserve,total}}
function finance(){const f=state.data.financeDashboard;if(!f)return `<h1>${t('finance')}</h1><div class="panel empty">${t('none')}</div>`;const typeName={BANK:['حساب بنكي','Bank account'],CASH:['خزنة / كاش','Cash vault'],CUSTODY:['عهدة نقدية','Cash custody'],WALLET:['محفظة إلكترونية','E-wallet']},accounts=f.balances||[],g=liquidityGuard_(),safe=Number(f.bookBalance||0)-g.total,month=String(f.generatedAt||new Date().toISOString()).slice(0,7);return `<h1>${t('finance')}</h1><div id="financeOutput" class="formal-report">${reportHeader_(state.lang==='ar'?'تقرير السيولة والأرصدة المالية':'Liquidity and financial balances',(state.lang==='ar'?'حتى ':'As of ')+esc(String(f.generatedAt||'').slice(0,10)))}<div class="finance-account-grid">${accounts.map(a=>`<article class="finance-account"><small>${state.lang==='ar'?(typeName[a.type]?.[0]||a.type):(typeName[a.type]?.[1]||a.type)}</small><h3>${esc(a.name)}</h3><strong>${money(a.balance)}</strong><span>${esc(a.currency||'EGP')} · ${state.lang==='ar'?'آخر تحديث':'Updated'} ${esc(String(a.lastUpdate||'—').slice(0,10))}</span></article>`).join('')}</div><div class="grid report-totals"><article class="card">${state.lang==='ar'?'الرصيد الدفتري':'Book balance'}<strong>${money(f.bookBalance)}</strong></article><article class="card">${state.lang==='ar'?'احتياطي أموال العملاء':'Client-funds reserve'}<strong>${money(g.clientReserve)}</strong></article><article class="card">${state.lang==='ar'?'التزامات الموردين المسجلة':'Recorded vendor commitments'}<strong>${money(g.vendorReserve)}</strong></article><article class="card">${state.lang==='ar'?`احتياطي مرتبات ${month}`:`${month} payroll reserve`}<strong>${money(g.payrollReserve)}</strong></article><article class="card">${state.lang==='ar'?`احتياطي إيجار ${month}`:`${month} rent reserve`}<strong>${money(g.rentReserve)}</strong></article><article class="card">${state.lang==='ar'?`الحد الأقصى للسحب لهذا الشهر (${month})`:`Maximum withdrawal for ${month}`}<strong>${money(safe)}</strong></article></div><div class="report-note">${state.lang==='ar'?'قد يظهر الحد الأقصى بالسالب لبيان العجز الحقيقي. الاحتياطيات الشهرية تُحسب مرة واحدة للشهر ولا تُضاعف المبالغ المدفوعة. الالتزامات الدورية الأخرى لا تدخل إلا بعد تسجيلها.':'The maximum may be negative to show the real shortfall. Monthly reserves are counted once and paid amounts are not duplicated. Other recurring obligations are included only after registration.'}</div><footer class="report-footer">FOOZIX Live · Arte Divino</footer></div><div class="actions no-print"><button id="printFinance" class="secondary">PDF / ${state.lang==='ar'?'طباعة ملخص السيولة والأرصدة':'Print liquidity and balances summary'}</button></div>`}
function select(name,label,items,id){return `<label class="field">${label}<select name="${name}"><option value=""></option>${items.map(x=>`<option value="${esc(x[id])}">${esc(state.lang==='ar'?(x['الاسم العربي']||x['الاسم']||x['الاسم الإنجليزي']):(x['الاسم الإنجليزي']||x['الاسم']||x['الاسم العربي']))}</option>`).join('')}</select></label>`}
function table(items){
  if(!items.length)return `<div class="panel empty">${t('none')}</div>`;
  const all=[...new Set(items.flatMap(x=>Object.keys(x||{})))];
  const hidden=/^(معرف|بصمة|الإصدار$|أنشئ في$|عدل في$|عدل بواسطة$|أرقام الحسابات$|أرقام الهواتف$|معرفات|قدرات العمل$)/;
  const preferred=['التاريخ','تاريخ العملية','التاريخ والوقت','تاريخ السلفة','تاريخ الشراء','الاسم العربي','الاسم الإنجليزي','الاسم','الوصف','البيان','النوع','الفئة','المشروع','الوظيفة','الهاتف','البريد','البنك','العملة','المبلغ','الإجمالي','الرصيد','الصافي','الحالة','الإجراء','الوحدة','المصدر','السبب','ملاحظات','أنشئ بواسطة'];
  const visible=all.filter(k=>!hidden.test(k));
  const keys=[...preferred.filter(k=>visible.includes(k)),...visible.filter(k=>!preferred.includes(k))].slice(0,9);
  const cell=(v,key)=>/تاريخ|date/i.test(key)?formatDateValue_(v):(v&&typeof v==='object'?JSON.stringify(v):v);
  return `<div class="panel table-wrap"><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${items.map(r=>`<tr>${keys.map(k=>`<td>${esc(cell(r[k],k))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`
}
function formatDateValue_(value){const raw=String(value??'').trim();if(!raw)return '—';if(/^\d{4}$/.test(raw))return state.lang==='ar'?`سنة ${raw}`:raw;let ms=null;if(typeof value==='number'&&value>20000&&value<80000)ms=Date.UTC(1899,11,30)+Math.round(value)*86400000;else if(/^\d{4}-\d{2}-\d{2}/.test(raw))ms=Date.parse(raw.slice(0,10)+'T00:00:00Z');else if(/^\d{1,2}[/-]\d{1,2}[/-]\d{4}$/.test(raw)){const [d,m,y]=raw.split(/[/-]/);ms=Date.UTC(Number(y),Number(m)-1,Number(d))}if(ms===null||Number.isNaN(ms))return raw;const d=new Date(ms);return `${String(d.getUTCDate()).padStart(2,'0')}/${String(d.getUTCMonth()+1).padStart(2,'0')}/${d.getUTCFullYear()}`}
async function list(key,sheet,module,filter){const r=await api('list',{sheet,module,pageSize:200,filter});if(r&&r.ok&&r.data)state.data[key]=r.data.items||[];else if(r)throw new Error(state.lang==='ar'?r.messageAr:r.messageEn)}
async function load(){try{const r=await api('view.load',{view:state.view});if(!r||!r.ok)throw new Error(state.lang==='ar'?r&&r.messageAr:r&&r.messageEn);state.data=Object.assign(state.data,r.data||{})}catch(e){state.notice={type:'error',text:e.message||String(e)};throw e}}
const obj=f=>{const o=Object.fromEntries(new FormData(f));f.querySelectorAll('input[type=checkbox]').forEach(x=>o[x.name]=x.checked);return o};
async function run(action,payload){const r=await api(action,payload);if(!r||!r.ok)throw new Error(r?(state.lang==='ar'?r.messageAr:r.messageEn):(state.lang==='ar'?'لم يصل رد من الخادم؛ أعد المحاولة':'No server response; retry'));state.notice={type:'ok',text:t('success')};await load();render()}
const fail=e=>{state.loading=false;state.notice={type:'error',text:e.message||String(e)};render()};
function printPrepared_(){let report=document.querySelector('.formal-report'),staging=null;if(!report&&state.data.financialStatements){const f=state.data.financialStatements;staging=document.createElement('div');staging.id='printStaging';staging.className='formal-report';staging.innerHTML=reportHeader_(state.lang==='ar'?'القوائم المالية':'Financial statements',`${f.period?.from||'—'} — ${f.period?.to||'—'}`)+`<div class="grid report-totals"><article class="card">الإيرادات<strong>${money(f.incomeStatement?.revenue)}</strong></article><article class="card">المصروفات<strong>${money(f.incomeStatement?.expenses)}</strong></article><article class="card">صافي الربح<strong>${money(f.incomeStatement?.netProfit)}</strong></article><article class="card">فرق التوازن<strong>${money(f.financialPosition?.balanceCheck)}</strong></article></div><h2>ميزان المراجعة</h2>${table(f.trialBalance||[])}<h2>التدفقات النقدية</h2>${table(f.cashFlow?.monthly||[])}<h2>ملخص الضريبة</h2>${table([f.taxSummary||{}])}`;document.querySelector('.content').appendChild(staging);report=staging}if(!report){fail(new Error(state.lang==='ar'?'أعد التقرير أولًا، ثم اضغط طباعة.':'Build the report first, then print.'));return}window.print();if(staging)setTimeout(()=>staging.remove(),1000)}
function wire(){const tx=document.querySelector('#tx');if(tx)tx.onsubmit=async e=>{e.preventDefault();try{const p=obj(tx),file=document.querySelector('#evidence').files[0];if(file){const data=await new Promise((ok,bad)=>{const reader=new FileReader();reader.onload=()=>ok(String(reader.result).split(',')[1]);reader.onerror=bad;reader.readAsDataURL(file)});const uploaded=await api('document.upload',{name:file.name,mimeType:file.type,base64:data});if(!uploaded.ok)throw new Error(state.lang==='ar'?uploaded.messageAr:uploaded.messageEn);p.documentId=uploaded.data['معرف المستند']}p.idempotencyKey=crypto.randomUUID();p.source='APPS_SCRIPT_WEB';await run('transaction.createAndSubmit',p)}catch(error){fail(error)}};const m=document.querySelector('#master');if(m)m.onsubmit=e=>{e.preventDefault();run('master.create',{entity:m.dataset.entity,record:obj(m)}).catch(fail)};const ef=document.querySelector('#employeeForm');if(ef)ef.onsubmit=e=>{e.preventDefault();run('master.create',{entity:'employee',record:obj(ef)}).catch(fail)};const ec=document.querySelector('#employeeChange');if(ec)ec.onsubmit=e=>{e.preventDefault();run('employee.change',obj(ec)).catch(fail)};const pf=document.querySelector('#payroll');if(pf)pf.onclick=()=>run('payroll.ensure',{}).catch(fail);const pd=document.querySelector('#payrollDetail');if(pd)pd.onsubmit=e=>{e.preventDefault();run('payroll.saveDetail',obj(pd)).catch(fail)};const sp=document.querySelector('#submitPayroll');if(sp)sp.onclick=()=>run('payroll.submit',{id:sp.dataset.id,version:sp.dataset.version}).catch(fail);const lp=document.querySelector('#lockPayroll');if(lp)lp.onclick=()=>run('payroll.lock',{id:lp.dataset.id,version:lp.dataset.version}).catch(fail);const lf=document.querySelector('#loanForm');if(lf)lf.onsubmit=e=>{e.preventDefault();run('loan.create',obj(lf)).catch(fail)};const af=document.querySelector('#assetForm');if(af)af.onsubmit=e=>{e.preventDefault();run('master.create',{entity:'asset',record:obj(af)}).catch(fail)};const auditFilter=document.querySelector('#filterAudit');if(auditFilter)auditFilter.onclick=()=>{const from=document.querySelector('#auditFrom').value,to=document.querySelector('#auditTo').value;state.data.audit=(state.data.audit||[]).filter(x=>(!from||String(x['التاريخ والوقت']).slice(0,10)>=from)&&(!to||String(x['التاريخ والوقت']).slice(0,10)<=to));render()};const auditPrint=document.querySelector('#printAudit');if(auditPrint)auditPrint.onclick=()=>window.print();const printFinance=document.querySelector('#printFinance');if(printFinance)printFinance.onclick=()=>window.print();const ds=document.querySelector('#driveSetup');if(ds)ds.onclick=()=>run('drive.setup',{}).catch(fail);const bn=document.querySelector('#backupNow');if(bn)bn.onclick=()=>run('backup.create',{reason:'Manual backup from settings'}).catch(fail);const bs=document.querySelector('#backupSchedule');if(bs)bs.onclick=()=>run('backup.schedule',{}).catch(fail);const alertSchedule=document.querySelector('#alertSchedule');if(alertSchedule)alertSchedule.onclick=()=>run('alerts.schedule',{}).catch(fail);const rb=document.querySelector('#restoreBackup');if(rb)rb.onclick=()=>run('backup.restore',{backupId:document.querySelector('#restoreBackupId').value,confirmation:document.querySelector('#restoreConfirm').value,reason:'Restore from settings'}).catch(fail);const loadReport=async mode=>{const projectId=document.querySelector('[name=reportProject]').value||state.data.reportProjectId;if(!projectId)return;state.data.reportProjectId=projectId;const r=await api('report.project',{projectId});if(!r.ok)throw new Error(state.lang==='ar'?r.messageAr:r.messageEn);state.data.projectReport=r.data;state.data.reportMode=mode;render()};const sr=document.querySelector('#summaryReport');if(sr)sr.onclick=()=>loadReport('summary').catch(fail);const dr=document.querySelector('#detailReport');if(dr)dr.onclick=()=>loadReport('detail').catch(fail);const pr=document.querySelector('#printReport');if(pr)pr.onclick=()=>window.print();document.querySelectorAll('.decision').forEach(b=>b.onclick=()=>run('approval.decide',{id:b.dataset.id,decision:b.dataset.value}).catch(fail))}
function buildProjectFinancialSummary_(projects){const normalized=(projects||[]).map(p=>{const expenses=Number(p['التكلفة الفعلية']||0),clientValue=Number(p['قيمة العميل']||0),receipts=Number(p['التحصيلات']||0)-Number(p['المردودات']||0),percentageDue=Number(p['إجمالي النسبة المستحقة']||p['الربح']||0),markupCollected=Number(p['النسبة المحصلة']||0),markupOutstanding=Number(p['النسبة غير المحصلة']||0),availableClientFunds=Number(p['الرصيد المتاح المعتمد']||0),outstanding=Math.max(0,clientValue-receipts);return {raw:p,expenses,clientValue,receipts,percentageDue,markupCollected,markupOutstanding,availableClientFunds,outstanding}}),archivedStatus=new Set(['ARCHIVED','CLOSED','COMPLETED','CANCELLED','مؤرشف','منتهي','مغلق','ملغي']),active=normalized.filter(x=>!archivedStatus.has(String(x.raw['الحالة التشغيلية']||'').trim().toUpperCase())),archived=normalized.filter(x=>!active.includes(x)),totals=active.reduce((t,p)=>(t.expenses+=p.expenses,t.clientValue+=p.clientValue,t.receipts+=p.receipts,t.percentageDue+=p.percentageDue,t.markupCollected+=p.markupCollected,t.markupOutstanding+=p.markupOutstanding,t.availableClientFunds+=p.availableClientFunds,t.outstanding+=p.outstanding,t),{expenses:0,clientValue:0,receipts:0,percentageDue:0,markupCollected:0,markupOutstanding:0,availableClientFunds:0,outstanding:0});return {active:active.map(x=>Object.assign({},x.raw,x)),archived:archived.map(x=>Object.assign({},x.raw,x)),totals}}
finance=function(){const f=state.data.financeDashboard;if(!f)return `<h1>${t('finance')}</h1><div class="panel empty">${t('none')}</div>`;const typeName={BANK:['حساب بنكي','Bank account'],CASH:['خزنة / كاش','Cash vault'],CUSTODY:['عهدة نقدية','Cash custody'],WALLET:['محفظة إلكترونية','E-wallet']},accounts=f.balances||[],ready=f.safeWithdrawalReady===true,missing=(f.missingInputs||[]).join('، ');return `<h1>${t('finance')}</h1><div id="financeOutput" class="formal-report">${reportHeader_(state.lang==='ar'?'تقرير السيولة والأرصدة المالية':'Liquidity and financial balances',(state.lang==='ar'?'حتى ':'As of ')+esc(String(f.generatedAt||'').slice(0,10)))}<div class="finance-account-grid">${accounts.map(a=>`<article class="finance-account"><small>${state.lang==='ar'?(typeName[a.type]?.[0]||a.type):(typeName[a.type]?.[1]||a.type)}</small><h3>${esc(a.name)}</h3><strong>${money(a.balance)}</strong><span>${esc(a.currency||'EGP')} · ${state.lang==='ar'?'آخر تحديث':'Updated'} ${esc(String(a.lastUpdate||'—').slice(0,10))}</span></article>`).join('')}</div><div class="grid report-totals"><article class="card">${state.lang==='ar'?'الرصيد الدفتري':'Book balance'}<strong>${money(f.bookBalance)}</strong></article><article class="card">${state.lang==='ar'?'الحد الأقصى الآمن للسحب':'Safe withdrawal amount'}<strong>${ready?money(f.safeWithdrawal):(state.lang==='ar'?'غير متاح':'Unavailable')}</strong></article></div><div class="report-note">${ready?(state.lang==='ar'?'تم احتسابه بعد خصم الالتزامات والاحتياطيات المسجلة.':'Calculated after recorded obligations and reserves.'):(state.lang==='ar'?`لن يعرض النظام رقمًا مضللًا قبل استكمال: ${esc(missing)}`:`The system will not show a misleading amount until these inputs are completed: ${esc(missing)}`)}</div><footer class="report-footer">FOOZIX Live · Arte Divino</footer></div><div class="actions no-print"><button id="printFinance" class="secondary">PDF / ${state.lang==='ar'?'طباعة ملخص السيولة والأرصدة':'Print liquidity and balances summary'}</button></div>`}
async function loadLeadershipProjectSummary_(){if(!['SUPER_ADMIN','ADMIN','PARTNER','FINANCIAL_MANAGER'].includes(String(state.profile?.role||'')))return;const r=await api('view.load',{view:'projects'});if(!r?.ok||!r.data?.projects)return;state.data.projectFinancialSummary=buildProjectFinancialSummary_(r.data.projects);render()}
function applyBootstrap_(data){if(!data||!data.profile)throw new Error(state.lang==='ar'?'تعذر تحميل بيانات الحساب':'Unable to load account data');if(data.sessionToken)storeSessionToken_(data.sessionToken);state.profile=data.profile;state.data=Object.assign(state.data,data.data||{});state.lang=state.profile.language||state.lang;state.loadedAt.dashboard=Date.now();render()}
async function boot(){
  syncMobileMode();splash();
  try{
    if(typeof finishGoogleLogin_==='function')await finishGoogleLogin_();
    await restoreSessionFromUrl_();
    if(!sessionToken_())return loginView();
    const r=await api('app.bootstrap');
    if(r&&r.ok)return applyBootstrap_(r.data);
    if(['SESSION_EXPIRED','AUTH_REQUIRED','USER_DISABLED','EMPLOYEE_INACTIVE'].includes(r?.code)){clearSessionToken_();return loginView()}
    throw new Error(r?(state.lang==='ar'?r.messageAr:r.messageEn):'Unable to load');
  }catch(error){
    const root=document.querySelector('#app');root.innerHTML=`<div class="splash"><div class="panel"><p>${esc(error.message||String(error))}</p><button id="retryBoot" type="button">${state.lang==='ar'?'إعادة المحاولة':'Retry'}</button></div></div>`;
    document.querySelector('#retryBoot').onclick=()=>boot();
  }
}
function txOptions(items,id,selected){return `<option value=""></option>${items.map(x=>`<option value="${esc(x[id])}" ${String(x[id])===String(selected||'')?'selected':''}>${esc(state.lang==='ar'?(x['الاسم العربي']||x['الاسم']||x['الوصف']||x['الاسم الإنجليزي']):(x['الاسم الإنجليزي']||x['الاسم']||x['الوصف']||x['الاسم العربي']))}</option>`).join('')}`}
function txSelectSmart(name,label,items,id,cls=''){return `<label class="field ${cls}">${label}<select name="${name}">${txOptions(items,id)}</select></label>`}
function txEvidence(){return `<label class="field field-wide">${state.lang==='ar'?'إثبات التحويل أو العملية':'Transfer or transaction evidence'}<input id="evidence" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"><input name="documentId" type="hidden"></label><label id="cashConfirm" class="check-line hidden"><input name="noEvidenceConfirmation" type="checkbox"><span>${state.lang==='ar'?'أؤكد مسؤولية التسجيل النقدي دون إثبات':'I confirm responsibility for an undocumented cash entry'}</span></label>`}
function txPayment(direction){const accountName=direction==='in'?'targetAccountId':'sourceAccountId',label=direction==='in'?(state.lang==='ar'?'حساب الاستلام':'Receiving account'):(state.lang==='ar'?'حساب الدفع':'Payment account');return `<label class="field">${t('payment')}<select name="paymentMethod"><option value=""></option><option value="CASH">${state.lang==='ar'?'نقدي':'Cash'}</option><option value="BANK_TRANSFER">${state.lang==='ar'?'تحويل بنكي':'Bank transfer'}</option><option value="CHEQUE">${state.lang==='ar'?'شيك':'Cheque'}</option></select></label>${txSelectSmart(accountName,label,state.data.cashAccounts||[],'معرف الحساب النقدي','account-field')}<label class="field reference-field">${t('reference')}<input name="reference"></label>`}
function txAmountAndTail(extra=''){return `${extra}<label class="field">${t('amount')}<input name="amount" type="number" min=".01" step=".01" required inputmode="decimal"></label>${txEvidence()}<label class="field field-wide">${t('notes')}<textarea name="notes" rows="3"></textarea></label><label id="duplicateConfirm" class="check-line hidden"><input name="confirmDuplicate" type="checkbox"><span>${state.lang==='ar'?'تأكيد إنشاء حركة جديدة رغم التطابق':'Confirm a new transaction despite the match'}</span></label><label id="agreementOverrun" class="check-line hidden"><input name="confirmAgreementOverrun" type="checkbox"><span>${state.lang==='ar'?'تأكيد تجاوز القيمة المعدلة للاتفاق':'Confirm exceeding the adjusted agreement value'}</span></label>`}
function txTaxFields(){return `<label class="check-line field-wide"><input name="taxable" type="checkbox"><span>${state.lang==='ar'?'معاملة ضريبية':'Tax transaction'}</span></label><div class="tax-fields hidden field-wide"><div class="form-grid"><label class="field">${state.lang==='ar'?'نسبة الضريبة %':'Tax rate %'}<input name="taxRate" type="number" value="14" min="0" max="100" step=".01"></label><label class="field">${state.lang==='ar'?'المبلغ':'Amount'}<select name="taxMode"><option value="EXCLUSIVE">${state.lang==='ar'?'غير شامل الضريبة':'Tax exclusive'}</option><option value="INCLUSIVE">${state.lang==='ar'?'شامل الضريبة':'Tax inclusive'}</option></select></label><label class="check-line"><input name="taxRecoverable" type="checkbox" checked><span>${state.lang==='ar'?'ضريبة مشتريات قابلة للاسترداد':'Recoverable input VAT'}</span></label><label class="field">${state.lang==='ar'?'رقم الفاتورة الضريبية':'Tax invoice number'}<input name="taxInvoiceNumber"></label><label class="field">${state.lang==='ar'?'تاريخ الفاتورة':'Invoice date'}<input name="taxInvoiceDate" type="date"></label><label class="field">${state.lang==='ar'?'مرجع الفاتورة الإلكترونية «اختياري»':'E-invoice reference (optional)'}<input name="eInvoiceReference"></label></div></div>`}
function txOperatingExpenseFields(){const items=state.data.expenseItems||[],groups=[...new Set(items.map(x=>x['المجموعة الرئيسية']))];return `<label class="field">${state.lang==='ar'?'المجموعة الرئيسية':'Main expense group'}<select name="expenseGroup" required><option value=""></option>${groups.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="field">${state.lang==='ar'?'بند المصروف':'Expense item'}<select name="expenseItemId" required><option value=""></option></select></label>`}
function txDynamicFields(type){const projects=state.data.projects||[],clients=state.data.clients||[],parties=state.data.parties||[],employees=state.data.employees||[],items=state.data.finishItems||[],agreements=state.data.agreements||[];const project=txSelectSmart('projectId',t('project'),projects,'معرف المشروع','project-field');const client=txSelectSmart('clientId',t('client'),clients,'معرف العميل','client-field');const party=txSelectSmart('partyId',state.lang==='ar'?'المورد أو المقاول':'Supplier or contractor',parties,'معرف الطرف','party-field');const employee=txSelectSmart('employeeId',t('employee'),employees,'معرف الموظف');const finish=txSelectSmart('finishItemId',state.lang==='ar'?'بند التشطيب':'Finishing item',items,'معرف البند');const agreement=txSelectSmart('agreementId',state.lang==='ar'?'الاتفاق المرتبط «اختياري»':'Linked agreement (optional)',agreements,'معرف الاتفاق','agreement-field');const desc=`<label class="field field-wide">${t('description')}<input name="description"></label>`;if(type==='PROJECT_EXPENSE')return `${project}<input type="hidden" name="clientId"><label class="field readonly-field">${t('client')}<input id="projectClientName" readonly></label>${party}${agreement}${finish}<label class="field">${state.lang==='ar'?'الكمية «اختياري»':'Quantity (optional)'}<input name="quantity" type="number" min="0" step=".01"></label><label class="field">${state.lang==='ar'?'الوحدة «اختياري»':'Unit (optional)'}<input name="unit" value="آخر"></label><label class="field">${state.lang==='ar'?'نسبة خاصة % «فارغة = نسبة المشروع»':'Override % (blank = project rate)'}<input name="markupRate" type="number" min="0" max="100" step=".01"></label>${desc}${txPayment('out')}${txAmountAndTail(`<div class="check-group field-wide"><label class="check-line"><input name="chargeClient" type="checkbox" checked><span>${state.lang==='ar'?'يُحمّل على العميل':'Charge client'}</span></label><label class="check-line"><input name="companyBears" type="checkbox"><span>${state.lang==='ar'?'تتحمله الشركة':'Company bears cost'}</span></label></div>`)} `;if(type==='CUSTOMER_RECEIPT')return `${client}${project}<label class="field">${state.lang==='ar'?'حساب/مرجع العميل «اختياري»':'Client account/reference (optional)'}<input name="clientAccount" value="آخر"></label>${txPayment('in')}${txAmountAndTail()}`;if(type==='INTERNAL_TRANSFER')return `${txSelectSmart('sourceAccountId',state.lang==='ar'?'من حساب':'From account',state.data.cashAccounts||[],'معرف الحساب النقدي')}${txSelectSmart('targetAccountId',state.lang==='ar'?'إلى حساب':'To account',state.data.cashAccounts||[],'معرف الحساب النقدي')}${txAmountAndTail()}`;if(type==='EMPLOYEE_LOAN')return `${employee}${txPayment('out')}${txAmountAndTail()}`;if(type==='EMPLOYEE_LOAN_REPAYMENT')return `${employee}${txPayment('in')}${txAmountAndTail()}`;if(type==='PAYROLL_PAYMENT')return `${txPayment('out')}${txAmountAndTail(desc)}`;if(type==='PARTNER_WITHDRAWAL')return `${employee}${txPayment('out')}${txAmountAndTail()}`;if(type==='PARTNER_DEPOSIT')return `${employee}${txPayment('in')}${txAmountAndTail()}`;if(type==='OPERATING_EXPENSE')return `${desc}${txPayment('out')}${txAmountAndTail()}`;if(type==='BANK_FEE')return `${desc}${txPayment('out')}${txAmountAndTail()}`;if(type==='FIXED_ASSET_PURCHASE')return `${desc}<label class="field">${state.lang==='ar'?'الموقع «اختياري»':'Location (optional)'}<input name="assetLocation"></label>${txPayment('out')}${txAmountAndTail()}`;if(type==='OPENING_BALANCE'||type==='ADJUSTMENT')return `${txSelectSmart('sourceAccountId',state.lang==='ar'?'الحساب الدائن':'Credit account',state.data.cashAccounts||[],'معرف الحساب النقدي')}${txSelectSmart('targetAccountId',state.lang==='ar'?'الحساب المدين':'Debit account',state.data.cashAccounts||[],'معرف الحساب النقدي')}${txAmountAndTail(desc)}`;return ''}
function txFormSmart(){const base=[['PROJECT_EXPENSE','مصروف مشروع / دفع مورد أو مقاول','Project expense / party payment','transactions'],['CUSTOMER_RECEIPT','تحصيل عميل','Customer receipt','transactions'],['INTERNAL_TRANSFER','تحويل داخلي','Internal transfer','transactions'],['EMPLOYEE_LOAN','سلفة موظف','Employee loan','loans'],['EMPLOYEE_LOAN_REPAYMENT','سداد سلفة','Loan repayment','loans'],['PAYROLL_PAYMENT','دفع رواتب','Payroll payment','payroll'],['PARTNER_WITHDRAWAL','مسحوبات شريك','Partner withdrawal','finance'],['PARTNER_DEPOSIT','إيداع شريك','Partner deposit','finance'],['OPERATING_EXPENSE','مصروف تشغيلي','Operating expense','transactions'],['BANK_FEE','رسوم بنكية','Bank fee','finance'],['FIXED_ASSET_PURCHASE','شراء أصل ثابت','Fixed asset purchase','assets']];if(canAction('finance','create'))base.push(['OPENING_BALANCE','رصيد افتتاحي','Opening balance','finance'],['ADJUSTMENT','تسوية محاسبية','Accounting adjustment','finance']);const types=base.filter(x=>canAction(x[3],'create'));const today=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);return `<h1>${t('transaction')}</h1><form id="tx" class="panel smart-form"><div class="form-grid"><label class="field">${t('date')}<input name="transactionDate" type="date" value="${today}" required></label><label class="field">${t('type')}<select name="type" required><option value=""></option>${types.map(x=>`<option value="${x[0]}">${state.lang==='ar'?x[1]:x[2]}</option>`).join('')}</select></label></div><div id="txDynamic" class="form-grid progressive"></div><button id="txSubmit" class="primary hidden">${t('submit')}</button></form>`}
function updateSmartTxDependencies(){const f=document.querySelector('#tx');if(!f)return;const type=f.type?.value,projectId=f.projectId?.value,clientId=f.clientId?.value,partyId=f.partyId?.value;if(type==='CUSTOMER_RECEIPT'&&f.projectId){const options=(state.data.projects||[]).filter(p=>!clientId||String(p['معرف العميل'])===String(clientId));f.projectId.innerHTML=txOptions(options,'معرف المشروع',projectId)}if(type==='PROJECT_EXPENSE'&&projectId){const p=(state.data.projects||[]).find(x=>String(x['معرف المشروع'])===String(projectId)),c=p&&(state.data.clients||[]).find(x=>String(x['معرف العميل'])===String(p['معرف العميل']));const out=document.querySelector('#projectClientName');if(out)out.value=c?(state.lang==='ar'?c['الاسم العربي']:c['الاسم الإنجليزي'])||c['الاسم العربي']:'';if(f.clientId)f.clientId.value=p?p['معرف العميل']:''}if(f.agreementId){const selected=f.agreementId.value,options=(state.data.agreements||[]).filter(a=>(!projectId||String(a['معرف المشروع'])===String(projectId))&&(!partyId||String(a['معرف الطرف'])===String(partyId))&&a['الحالة']==='ACTIVE');f.agreementId.innerHTML=txOptions(options,'معرف الاتفاق',selected)}const payment=f.paymentMethod?.value,accountType=payment==='CASH'?['CASH','CUSTODY']:['BANK_TRANSFER','CHEQUE'].includes(payment)?['BANK']:null;f.querySelectorAll('.account-field select').forEach(s=>{const selected=s.value,options=accountType?(state.data.cashAccounts||[]).filter(a=>accountType.includes(a['النوع'])):(state.data.cashAccounts||[]);s.innerHTML=txOptions(options,'معرف الحساب النقدي',selected)});const evidence=document.querySelector('#evidence'),cash=payment==='CASH'&&!evidence?.files?.length;document.querySelector('#cashConfirm')?.classList.toggle('hidden',!cash);const charge=f.chargeClient,company=f.companyBears;if(charge&&company){charge.onchange=()=>{if(charge.checked)company.checked=false};company.onchange=()=>{if(company.checked)charge.checked=false}}}
async function submitSmartTx(f){const p=obj(f),file=document.querySelector('#evidence')?.files?.[0];try{if(file){const data=await new Promise((ok,bad)=>{const reader=new FileReader();reader.onload=()=>ok(String(reader.result).split(',')[1]);reader.onerror=bad;reader.readAsDataURL(file)});const uploaded=await api('document.upload',{name:file.name,mimeType:file.type,base64:data});if(!uploaded.ok)throw new Error(state.lang==='ar'?uploaded.messageAr:uploaded.messageEn);p.documentId=uploaded.data['معرف المستند']}p.idempotencyKey=f.dataset.requestKey||(f.dataset.requestKey=crypto.randomUUID());p.source='APPS_SCRIPT_WEB';const r=await api('transaction.createAndSubmit',p);if(!r.ok){if(r.code==='POTENTIAL_DUPLICATE'){document.querySelector('#duplicateConfirm')?.classList.remove('hidden');throw new Error(state.lang==='ar'?r.messageAr:r.messageEn)}if(r.code==='AGREEMENT_LIMIT_EXCEEDED'){document.querySelector('#agreementOverrun')?.classList.remove('hidden');throw new Error(state.lang==='ar'?r.messageAr:r.messageEn)}throw new Error(state.lang==='ar'?r.messageAr:r.messageEn)}state.notice={type:'ok',text:t('success')};await load();render()}catch(e){const n=document.querySelector('.notice');if(n){n.className='notice error';n.textContent=e.message}else alert(e.message)}}
function installSmartListeners(){document.addEventListener('change',async e=>{const f=e.target.closest&&e.target.closest('#tx');if(!f)return;if(e.target.name==='type'){if(e.target.value==='PROJECT_EXPENSE'&&!state.data.agreements){const r=await api('agreement.list',{});if(r.ok)state.data.agreements=r.data||[]}document.querySelector('#txDynamic').innerHTML=txDynamicFields(e.target.value);document.querySelector('#txSubmit').classList.toggle('hidden',!e.target.value);f.onsubmit=x=>{x.preventDefault();submitSmartTx(f)};}updateSmartTxDependencies()});document.addEventListener('click',e=>{if(e.target.closest&&e.target.closest('[data-add-phone]')){const host=e.target.closest('.repeat-group'),input=host.querySelector('input');if(input.value.trim()){const chip=document.createElement('span');chip.className='chip';chip.dataset.value=input.value.trim();chip.innerHTML=`${esc(input.value.trim())}<button type="button" data-remove-chip>×</button>`;host.querySelector('.chips').appendChild(chip);input.value=''}}if(e.target.matches&&e.target.matches('[data-remove-chip]'))e.target.closest('.chip').remove()})}
function phoneGroup(){return `<div class="field field-wide repeat-group"><span>${t('phone')}</span><div class="inline-add"><input type="tel" inputmode="tel"><button type="button" class="secondary icon-button" data-add-phone>＋</button></div><div class="chips"></div></div>`}
function clientForm(){return `<form id="smartMaster" data-entity="client" class="panel"><h2>${state.lang==='ar'?'إضافة عميل':'Add client'}</h2><div class="form-grid"><label class="field">${t('nameAr')}<input name="الاسم العربي" required></label><label class="field">${t('nameEn')}<input name="الاسم الإنجليزي"></label>${phoneGroup()}<label class="field">${t('email')}<input name="البريد" type="email"></label><label class="field">${t('address')} «${state.lang==='ar'?'اختياري':'optional'}»<input name="العنوان"></label><div class="field field-wide repeat-group account-group"><span>${state.lang==='ar'?'أرقام حساب العميل «اختياري»':'Client account numbers (optional)'}</span><div class="inline-add"><input><button type="button" class="secondary icon-button" data-add-phone>＋</button></div><div class="chips"></div></div></div><button class="primary">${t('add')}</button></form>`}
function partyForm(){return `<form id="smartMaster" data-entity="party" class="panel"><h2>${state.lang==='ar'?'إضافة مورد أو مقاول':'Add supplier or contractor'}</h2><div class="form-grid"><label class="field">${state.lang==='ar'?'النوع':'Type'}<select name="النوع"><option value="مورد">${state.lang==='ar'?'مورد':'Supplier'}</option><option value="مقاول">${state.lang==='ar'?'مقاول':'Contractor'}</option><option value="مورد ومقاول">${state.lang==='ar'?'مورد ومقاول':'Both'}</option></select></label><label class="field">${t('nameAr')}<input name="الاسم العربي" required></label><label class="field">${t('nameEn')}<input name="الاسم الإنجليزي"></label>${phoneGroup()}<label class="field">${t('email')}<input name="البريد" type="email"></label><label class="field field-wide">${state.lang==='ar'?'التخصصات «يمكن اختيار أكثر من بند»':'Specialties (multiple allowed)'}<select name="specialtyIds" multiple size="6">${txOptions(state.data.finishItems||[],'معرف البند')}</select></label></div><button class="primary">${t('add')}</button></form>`}
function projectForm(){const types=['سكني','تجاري','إداري','طبي','فندقي','تنسيق مواقع','تجديد وإعادة تأهيل','أخرى'];return `<form id="smartMaster" data-entity="project" class="panel"><h2>${state.lang==='ar'?'إضافة مشروع':'Add project'}</h2><div class="form-grid">${select('معرف العميل',t('client'),state.data.clients||[],'معرف العميل')}<label class="field">${t('nameAr')}<input name="الاسم العربي" required></label><label class="field">${t('nameEn')}<input name="الاسم الإنجليزي"></label><label class="field field-wide">${state.lang==='ar'?'عنوان المشروع':'Project address'}<input name="العنوان"></label><label class="field">${state.lang==='ar'?'نوع المشروع':'Project type'}<select name="نوع المشروع">${types.map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field">${state.lang==='ar'?'نسبة المشروع %':'Project rate %'}<input name="النسبة العامة" type="number" min="0" max="100" step=".01" required></label><label class="field">${state.lang==='ar'?'قيمة التصميم':'Design value'}<input name="قيمة التصميم" type="number" min="0" step=".01"></label><label class="check-line"><input id="hasContract" name="يوجد عقد" type="checkbox"><span>${state.lang==='ar'?'يوجد عقد':'Contract exists'}</span></label><label id="contractValue" class="field hidden">${state.lang==='ar'?'قيمة العقد':'Contract value'}<input name="قيمة العقد" type="number" min="0" step=".01"></label></div><button class="primary">${t('add')}</button></form>`}
function agreementName(a){const party=(state.data.parties||[]).find(x=>String(x['معرف الطرف'])===String(a['معرف الطرف'])),project=(state.data.projects||[]).find(x=>String(x['معرف المشروع'])===String(a['معرف المشروع']));return `${party?(party['الاسم العربي']||party['الاسم الإنجليزي']):a['معرف الطرف']} — ${project?(project['الاسم العربي']||project['الاسم الإنجليزي']):a['معرف المشروع']}`}
function agreementOptions(list){return `<option value=""></option>${list.map(a=>`<option value="${esc(a['معرف الاتفاق'])}">${esc(agreementName(a))}</option>`).join('')}`}
function agreementTable(list){if(!list.length)return `<div class="empty">${t('none')}</div>`;const rows=list.map(a=>({'الطرف / المشروع':agreementName(a),'القيمة الأصلية':a['القيمة الأصلية'],'التعديلات':a['إجمالي التعديلات'],'القيمة المعدلة':a['القيمة المعدلة'],'الأعمال المعتمدة':a['قيمة الأعمال المعتمدة'],'المدفوع':a['إجمالي المدفوع'],'المتبقي':a['المتبقي من الاتفاق'],'المستحق حاليًا':a['المستحق حاليًا'],'الحالة':a['الحالة']}));return table(rows)}
function agreementPanel(){if(!canAction('agreements','view'))return '';const list=state.data.agreements||[],editable=canAction('agreements','edit');return `${canAction('agreements','create')?`<form id="agreementForm" class="panel"><h2>${state.lang==='ar'?'اتفاق جديد مع مورد أو مقاول':'New party agreement'}</h2><p class="muted">${state.lang==='ar'?'الإلزامي فقط: الطرف، المشروع، وقيمة الاتفاق. باقي البيانات اختيارية.':'Only party, project and value are required. Everything else is optional.'}</p><div class="form-grid">${select('partyId',state.lang==='ar'?'المورد أو المقاول':'Supplier or contractor',state.data.parties||[],'معرف الطرف')}${select('projectId',t('project'),state.data.projects||[],'معرف المشروع')}${select('finishItemId',state.lang==='ar'?'بند التشطيب «اختياري»':'Finishing item (optional)',state.data.finishItems||[],'معرف البند')}<label class="field">${state.lang==='ar'?'قيمة الاتفاق':'Agreement value'}<input name="amount" type="number" min=".01" step=".01" required></label><label class="field">${state.lang==='ar'?'تاريخ الاتفاق «اختياري»':'Agreement date (optional)'}<input name="agreementDate" type="date"></label><label class="field field-wide">${state.lang==='ar'?'نطاق العمل/الوصف «اختياري»':'Scope/description (optional)'}<input name="description"></label><label class="field field-wide">${t('notes')} «${state.lang==='ar'?'اختياري':'optional'}»<textarea name="notes"></textarea></label><label class="field field-wide">${state.lang==='ar'?'مستند الاتفاق «اختياري»':'Agreement document (optional)'}<input name="agreementDocument" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"></label><label class="check-line"><input name="requireApproval" type="checkbox"><span>${state.lang==='ar'?'طلب اعتماد للاتفاق «اختياري»':'Request agreement approval (optional)'}</span></label></div><button class="primary">${t('save')}</button></form>`:''}${editable?`<details class="panel"><summary>${state.lang==='ar'?'تعديل قيمة اتفاق مع حفظ التاريخ':'Amend an agreement with history'}</summary><form id="agreementAmend"><div class="form-grid"><label class="field">${state.lang==='ar'?'الاتفاق':'Agreement'}<select name="agreementId" required>${agreementOptions(list)}</select></label><label class="field">${state.lang==='ar'?'قيمة التعديل «موجب زيادة / سالب خصم»':'Amendment (+ increase / - reduction)'}<input name="amount" type="number" step=".01" required></label><label class="field">${state.lang==='ar'?'التاريخ «اختياري»':'Date (optional)'}<input name="date" type="date"></label><label class="field field-wide">${state.lang==='ar'?'السبب/الوصف «اختياري»':'Reason/description (optional)'}<input name="description"></label><label class="field field-wide">${state.lang==='ar'?'مستند «اختياري»':'Document (optional)'}<input name="amendDocument" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"></label></div><button class="primary">${t('save')}</button></form></details><details class="panel"><summary>${state.lang==='ar'?'تحديث قيمة الأعمال المعتمدة «اختياري»':'Update certified work value (optional)'}</summary><form id="agreementCertify"><div class="form-grid"><label class="field">${state.lang==='ar'?'الاتفاق':'Agreement'}<select name="agreementId" required>${agreementOptions(list)}</select></label><label class="field">${state.lang==='ar'?'قيمة الأعمال المعتمدة':'Certified work value'}<input name="certifiedValue" type="number" min="0" step=".01" required></label><label class="field field-wide">${t('notes')} «${state.lang==='ar'?'اختياري':'optional'}»<input name="notes"></label></div><button class="primary">${t('save')}</button></form></details>`:''}<div class="panel"><div class="section-heading"><h2>${state.lang==='ar'?'الاتفاقات والأرصدة':'Agreements and balances'}</h2><button id="printAgreements" class="secondary" type="button">PDF / ${state.lang==='ar'?'طباعة':'Print'}</button></div>${agreementTable(list)}</div>`}
function masterSmart(k){const items=state.data[k]||[];const form=k==='clients'?clientForm():k==='parties'?partyForm():projectForm();return `<h1>${t(k)}</h1>${form}${k==='parties'?agreementPanel():''}${table(items)}`}
function employeesSmart(){const cycles=state.data.payrollCycles||[],cycle=cycles[0],details=state.data.payrollDetails||[],people=state.data.employees||[],jobs=['مصمم','مصم داخلي','مهندس معماري','مهندس مدني','مهندس موقع','مهندس كهرباء','مهندس ميكانيكا','مدير مشروع','محاسب','مسؤول موارد بشرية','مشتريات','مشرف موقع','فني','عامل','إداري','أخرى'];return `<h1>${t('employees')}</h1><form id="employeeForm" class="panel"><h2>${state.lang==='ar'?'إضافة موظف':'Add employee'}</h2><div class="form-grid"><label class="field">${t('nameAr')}<input name="الاسم العربي" required></label><label class="field">${t('nameEn')}<input name="الاسم الإنجلي"></label><label class="field">${t('email')}<input name="البريد" type="email" required></label>${phoneGroup()}<label class="field">${state.lang==='ar'?'الوظيفة':'Job title'}<select name="الوظيفة"><option value=""></option>${jobs.map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field">${state.lang==='ar'?'الراتب الأساسي':'Base salary'}<input name="الراتب الأساسي" type="number" min="0" step=".01"></label><label class="field">${state.lang==='ar'?'تاريخ التعيين':'Hire date'}<input name="تاريخ التعيين" type="date"></label><label class="field">${t('role')}<select name="role"><option value="SITE_ENGINEER">مهندس موقع — Site Engineer</option><option value="HR_ADMIN">مسؤول إداري — HR Admin</option><option value="MANAGER">مدير — Manager</option><option value="PARTNER">شريك — Partner</option></select></label><label class="check-line"><input name="السماح بالدخول" type="checkbox"><span>${state.lang==='ar'?'السماح بالدخول':'Allow login'}</span></label></div><div class="actions"><button class="primary">${t('add')}</button><button id="payroll" type="button" class="secondary">${t('openPayroll')}</button></div></form><details class="panel"><summary>${state.lang==='ar'?'زيادة مرتب أو ترقية':'Salary increase or promotion'}</summary><form id="employeeChange"><div class="form-grid">${select('employeeId',t('employee'),people,'معرف الموظف')}<label class="field">${state.lang==='ar'?'نوع التغيير':'Change type'}<select name="changeType"><option value="SALARY">${state.lang==='ar'?'تعديل راتب':'Salary change'}</option><option value="PROMOTION">${state.lang==='ar'?'ترقية':'Promotion'}</option></select></label><label class="field">${state.lang==='ar'?'القيمة الجديدة':'New value'}<input name="newValue" required></label><label class="field">${state.lang==='ar'?'تاريخ السريان':'Effective date'}<input name="effectiveDate" type="date" required></label><label class="field">${t('notes')}<input name="reason"></label></div><button class="primary">${t('submit')}</button></form></details>${cycle?payrollPanel(cycle,details,people):''}${table(people)}`}
function loansSmart(){const loans=state.data.loans||[],balances=state.data.historicalPeopleBalances||[],history=state.data.historicalFinancialMovements||[];return `<h1>${t('loans')}</h1><div class="panel"><p>${state.lang==='ar'?'يعرض الأرصدة المحسوبة من كل الحركات المرحلة والحالية. أي حركة جديدة تُسجل من الحركة اليومية وتنعكس هنا تلقائيًا.':'Balances are calculated from all migrated and current movements. New daily transactions appear here automatically.'}</p></div>${balances.length?`<div class="panel"><h2>${state.lang==='ar'?'ملخص أرصدة السلف وجاري الشركاء':'Loans and partner current-account balances'}</h2>${table(balances)}</div>`:''}${loans.length?`<div class="panel"><h2>${state.lang==='ar'?'جدول السلف والأقساط التشغيلية':'Operational loan installments'}</h2>${table(loans)}</div>`:''}${history.length?`<details class="panel"><summary>${state.lang==='ar'?'عرض تفاصيل الحركات التاريخية':'Show historical movement details'}</summary>${table(history)}</details>`:`<div class="panel empty">${t('none')}</div>`}`}
function financeSmart(){const accounts=(state.data.cashAccounts||[]).filter(x=>x['النوع']==='BANK'),statements=state.data.bankStatements||[];return `${canAction('finance','create')?`<form id="bankAccountForm" class="panel"><h2>${state.lang==='ar'?'إنشاء حساب بنكي أو نقدي جديد':'Create a bank or cash account'}</h2><div class="form-grid"><label class="field">${state.lang==='ar'?'نوع الحساب':'Account type'}<select name="النوع"><option value="BANK">${state.lang==='ar'?'بنك':'Bank'}</option><option value="CASH">${state.lang==='ar'?'خزنة':'Cash vault'}</option><option value="CUSTODY">${state.lang==='ar'?'عهدة نقدية':'Cash custody'}</option></select></label><label class="field">${state.lang==='ar'?'اسم الحساب':'Account name'}<input name="الاسم" required></label><label class="field">${state.lang==='ar'?'البنك':'Bank'}<input name="البنك"></label><label class="field">${state.lang==='ar'?'الفرع':'Branch'}<input name="الفرع"></label><label class="field">${t('currency')}<input name="العملة" value="EGP"></label><label class="field">${state.lang==='ar'?'رقم الحساب المقنّع':'Masked account number'}<input name="رقم مقنع"></label><label class="field">${state.lang==='ar'?'رصيد افتتاحي':'Opening balance'}<input name="الرصيد الافتتاحي" type="number" step=".01" value="0"></label>${select('معرف حساب الأستاذ',state.lang==='ar'?'حساب الأستاذ المرتبط':'Mapped ledger account',state.data.ledgerAccounts||[],'معرف الحساب')}</div><button class="primary">${t('save')}</button></form><form id="bankStatementForm" class="panel"><h2>${state.lang==='ar'?'رفع ومطابقة كشف حساب بنكي':'Upload and reconcile bank statement'}</h2><div class="form-grid">${select('accountId',state.lang==='ar'?'الحساب البنكي أولًا':'Choose bank account first',accounts,'معرف الحساب النقدي')}<div id="previousStatement" class="field field-wide hint">${state.lang==='ar'?'اختر الحساب لعرض آخر كشف معتمد والبنود المرحلة':'Choose an account to show the previous statement and carried items'}</div><label class="field">${state.lang==='ar'?'من تاريخ — الفترة الجديدة':'From — new period'}<input name="fromDate" type="date" required></label><label class="field">${state.lang==='ar'?'إلى تاريخ — الفترة الجديدة':'To — new period'}<input name="toDate" type="date" required></label><label class="field">${state.lang==='ar'?'الرصيد الافتتاحي بالكشف الجديد':'New statement opening balance'}<input name="openingBalance" type="number" step=".01" required></label><label class="field">${state.lang==='ar'?'الرصيد الختامي بالكشف الجديد':'New statement closing balance'}<input name="closingBalance" type="number" step=".01" required></label><label class="field">${state.lang==='ar'?'المصاريف البنكية الجديدة':'New bank fees'}<input name="bankFees" type="number" min="0" step=".01" value="0" required></label><details class="field field-wide"><summary>${state.lang==='ar'?'تفاصيل المطابقة الإضافية':'Additional reconciliation details'}</summary><div class="form-grid"><label class="field">${state.lang==='ar'?'إيداعات معلقة مرحلة/مؤكدة':'Carried/confirmed outstanding deposits'}<input name="outstandingDeposits" type="number" step=".01" value="0"></label><label class="field">${state.lang==='ar'?'مدفوعات معلقة مرحلة/مؤكدة':'Carried/confirmed outstanding payments'}<input name="outstandingPayments" type="number" step=".01" value="0"></label><label class="field">${state.lang==='ar'?'تسويات أخرى بسبب واضح':'Other explained adjustments'}<input name="adjustments" type="number" step=".01" value="0"></label></div></details><label class="field">${state.lang==='ar'?'ملف كشف البنك PDF':'Bank statement PDF'}<input name="statementFile" type="file" accept="application/pdf,image/jpeg,image/png" required></label><label class="field field-wide">${t('notes')}<input name="notes"></label></div><button class="primary">${state.lang==='ar'?'رفع وبدء المطابقة':'Upload and reconcile'}</button></form>`:''}${finance()}<div class="panel"><h2>${state.lang==='ar'?'كشوف البنك والمطابقات':'Bank statements and reconciliations'}</h2>${table(statements)}</div>`}

async function loadBankStatementDefaults(selectEl){const f=selectEl&&selectEl.form;if(!f||!selectEl.value)return;const r=await api('bank.statement.defaults',{accountId:selectEl.value});if(!r.ok)throw new Error(msg(r));const d=r.data||{},box=f.querySelector('#previousStatement');if(!d.hasPrevious){box.textContent=state.lang==='ar'?'لا يوجد كشف سابق لهذا الحساب':'No previous statement for this account';return}box.textContent=state.lang==='ar'?`السابق: من ${d.fromDate||'-'} إلى ${d.toDate||'-'} — الختامي ${money(d.closingBalance)} — الحالة ${d.status||'-'}`:`Previous: ${d.fromDate||'-'} to ${d.toDate||'-'} — closing ${money(d.closingBalance)} — ${d.status||'-'}`;f.outstandingDeposits.value=d.outstandingDeposits||0;f.outstandingPayments.value=d.outstandingPayments||0;f.adjustments.value=0;}
function collectRepeated(form){const values=selector=>[...form.querySelectorAll(selector)].map(x=>x.dataset.value||x.value).map(x=>String(x||'').trim()).filter(Boolean);return {phones:values('.repeat-group:not(.account-group) .chip,.repeat-group:not(.account-group) .inline-add input'),accountNumbers:values('.account-group .chip,.account-group .inline-add input')}}
async function uploadOptionalFile(form,inputName){const input=form.elements[inputName],file=input&&input.files&&input.files[0];if(!file)return '';const data=await new Promise((ok,bad)=>{const reader=new FileReader();reader.onload=()=>ok(String(reader.result).split(',')[1]);reader.onerror=bad;reader.readAsDataURL(file)}),uploaded=await api('document.upload',{name:file.name,mimeType:file.type,base64:data});if(!uploaded.ok)throw new Error(state.lang==='ar'?uploaded.messageAr:uploaded.messageEn);return uploaded.data['معرف المستند']}
function installMasterListeners(){document.addEventListener('change',e=>{if(e.target.getAttribute('id')==='hasContract')document.querySelector('#contractValue')?.classList.toggle('hidden',!e.target.checked);if(e.target.form?.id==='bankStatementForm'&&e.target.name==='accountId')loadBankStatementDefaults(e.target).catch(fail)});document.addEventListener('submit',async e=>{const f=e.target;try{if(f.getAttribute('id')==='smartMaster'){e.preventDefault();const p=obj(f),extra=collectRepeated(f);p.phones=extra.phones;p.accountNumbers=extra.accountNumbers;if(f.specialtyIds)p.specialtyIds=[...f.specialtyIds.selectedOptions].map(x=>x.value).filter(Boolean);await run('master.create',{entity:f.dataset.entity,record:p})}if(f.getAttribute('id')==='employeeForm'){e.preventDefault();e.stopImmediatePropagation();const p=obj(f),extra=collectRepeated(f);p.phones=extra.phones;p['الهاتف']=extra.phones[0]||'';await run('master.create',{entity:'employee',record:p})}if(f.getAttribute('id')==='agreementForm'){e.preventDefault();const p=obj(f);p.documentId=await uploadOptionalFile(f,'agreementDocument');delete p.agreementDocument;await run('agreement.create',p)}if(f.getAttribute('id')==='agreementAmend'){e.preventDefault();const p=obj(f);p.documentId=await uploadOptionalFile(f,'amendDocument');delete p.amendDocument;await run('agreement.amend',p)}if(f.getAttribute('id')==='agreementCertify'){e.preventDefault();await run('agreement.certify',obj(f))}if(f.getAttribute('id')==='bankAccountForm'){e.preventDefault();await run('master.create',{entity:'cashAccount',record:obj(f)})}if(f.getAttribute('id')==='bankStatementForm'){e.preventDefault();const p=obj(f);p.documentId=await uploadOptionalFile(f,'statementFile');delete p.statementFile;await run('bank.statement.create',p)}}catch(error){fail(error)}},true);document.addEventListener('click',e=>{if(e.target.getAttribute('id')==='printAgreements')window.print()})}
const baseLoad=load;load=async function(){await baseLoad();if(state.view==='parties'){await Promise.all([list('projects','المشروعات','projects'),list('finishItems','بنود التشطيبات','projects')]);const r=await api('agreement.list',{});if(r.ok)state.data.agreements=r.data||[]}if(state.view==='finance'&&canAction('finance','create'))await list('ledgerAccounts','دليل الحسابات','finance')};
installSmartListeners();installMasterListeners();
const txDynamicFieldsOriginal=txDynamicFields;
function txInvoiceTaxFields(){return `<label class="check-line field-wide"><input name="taxable" type="checkbox"><span>${state.lang==='ar'?'فاتورة ضريبية':'Tax invoice'}</span></label><div class="tax-fields hidden field-wide"><div class="form-grid"><label class="field">${state.lang==='ar'?'نسبة ضريبة القيمة المضافة %':'VAT rate %'}<input name="taxRate" type="number" value="14" min="0" max="100" step=".01"></label><label class="field">${state.lang==='ar'?'قيمة الفاتورة':'Invoice amount'}<select name="taxMode"><option value="EXCLUSIVE">${state.lang==='ar'?'غير شاملة الضريبة':'Tax exclusive'}</option><option value="INCLUSIVE">${state.lang==='ar'?'شاملة الضريبة':'Tax inclusive'}</option></select></label><label class="field">${state.lang==='ar'?'رقم الفاتورة الضريبية':'Tax invoice number'}<input name="taxInvoiceNumber"></label><label class="field">${state.lang==='ar'?'تاريخ الفاتورة':'Invoice date'}<input name="taxInvoiceDate" type="date"></label><label class="field">${state.lang==='ar'?'مرجع الفاتورة الإلكترونية «اختياري»':'E-invoice reference (optional)'}<input name="eInvoiceReference"></label></div></div>`}
txDynamicFields=function(type){
  if(type==='BANK_INTEREST')return `<label class="field field-wide">${t('description')}<input name="description" required></label>${txPayment('in')}${txAmountAndTail()}`;
  if(type==='PROJECT_INVOICE'){const projects=state.data.projects||[],clients=state.data.clients||[];return `${txSelectSmart('clientId',t('client'),clients,'معرف العميل','client-field')}${txSelectSmart('projectId',t('project'),projects,'معرف المشروع','project-field')}<label class="field field-wide">${t('description')}<input name="description" required></label>${txInvoiceTaxFields()}${txAmountAndTail()}`}
  if(type==='OPERATING_EXPENSE')return `${txOperatingExpenseFields()}<label class="field field-wide">${t('description')}<input name="description"></label>${txPayment('out')}${txTaxFields()}${txAmountAndTail()}`;
  const html=txDynamicFieldsOriginal(type);
  return ['PROJECT_EXPENSE','FIXED_ASSET_PURCHASE'].includes(type)?html.replace(`<label class="field">${t('amount')}`,`${txTaxFields()}<label class="field">${t('amount')}`):html;
};
