document.addEventListener('change',e=>{if(e.target.form?.id!=='notificationPreferences'||e.target.name!=='userId')return;const u=(state.data.systemUsers||[]).find(x=>String(x['معرف المستخدم'])===String(e.target.value)),f=e.target.form;if(!u)return;f.inApp.checked=u['إشعارات داخل التطبيق']===''||u['إشعارات داخل التطبيق']==null||isTrue_(u['إشعارات داخل التطبيق']);f.email.checked=u['إشعارات البريد']===''||u['إشعارات البريد']==null||isTrue_(u['إشعارات البريد']);f.level.value=u['مستوى الإشعارات']||'ALL'});
document.addEventListener('submit',async e=>{if(e.target.getAttribute('id')!=='notificationPreferences')return;e.preventDefault();e.stopImmediatePropagation();const f=e.target;await run('notification.preferences.update',{userId:f.userId.value,inApp:f.inApp.checked,email:f.email.checked,level:f.level.value})},true);
document.addEventListener('submit',async e=>{if(e.target.getAttribute('id')!=='permissionForm')return;e.preventDefault();e.stopImmediatePropagation();await run('permission.set',obj(e.target))},true);

document.addEventListener('click',async e=>{try{
  if(e.target.classList.contains('notification-read'))await run('notification.read',{id:e.target.dataset.id});
  if(e.target.getAttribute('id')==='readAllNotifications')await run('notification.readAll',{});
  if(e.target.getAttribute('id')==='enableDeviceNotifications'&&'Notification'in window){const permission=await Notification.requestPermission();if(permission==='granted')new Notification('FOOZIX Live',{body:state.lang==='ar'?'تم تفعيل إشعارات هذا الجهاز':'Device notifications enabled'})}
  if(e.target.classList.contains('bank-review'))await run('bank.statement.review',{id:e.target.dataset.id,version:Number(e.target.dataset.version||1),decision:e.target.dataset.decision,notes:''});
  if(e.target.getAttribute('id')==='loadFinancialStatements'){const r=await api('finance.statements',{fromDate:document.querySelector('#financialFrom').value,toDate:document.querySelector('#financialTo').value});if(!r.ok)throw new Error(msg(r));state.data.financialStatements=r.data;render()}
  if(e.target.getAttribute('id')==='printFinancialStatements')window.print();
}catch(error){fail(error)}},true);
