const txDynamicFieldsPartnerBase_=txDynamicFields;
txDynamicFields=function(type){
  if(!['PARTNER_WITHDRAWAL','PARTNER_DEPOSIT'].includes(type))return txDynamicFieldsPartnerBase_(type);
  const partners=(state.data.employees||[]).filter(employee=>isTrue_(employee['هل شريك']));
  const partner=txSelectSmart('employeeId',state.lang==='ar'?'الشريك':'Partner',partners,'معرف الموظف');
  return `${partner}${txPayment(type==='PARTNER_WITHDRAWAL'?'out':'in')}${txAmountAndTail()}`;
};

function partyCapabilityIds_(partyId){
  if(!partyId)return [];
  const party=(state.data.parties||[]).find(item=>String(item['معرف الطرف'])===String(partyId));
  let capabilities=[];
  try{capabilities=JSON.parse(party?.['قدرات العمل']||'[]')}catch(ignore){capabilities=[]}
  const ids=capabilities.map(item=>item.finishItemId).filter(Boolean);
  (state.data.agreements||[]).filter(item=>String(item['معرف الطرف'])===String(partyId)&&item['الحالة']==='ACTIVE').forEach(item=>{if(item['معرف بند التشطيب'])ids.push(item['معرف بند التشطيب'])});
  return [...new Set(ids.map(String))];
}
const updateSmartTxDependenciesPartyBase_=updateSmartTxDependencies;
updateSmartTxDependencies=function(){
  updateSmartTxDependenciesPartyBase_();
  const form=document.querySelector('#tx');
  if(!form||form.type?.value!=='PROJECT_EXPENSE'||!form.finishItemId)return;
  const selected=form.finishItemId.value,partyId=form.partyId?.value;
  if(!partyId)return;
  const allowed=new Set(partyCapabilityIds_(partyId));
  const items=(state.data.finishItems||[]).filter(item=>allowed.has(String(item['معرف البند'])));
  form.finishItemId.innerHTML=txOptions(items,'معرف البند',selected);
};

function financialPeriodPanel_(){const rows=state.data.financialPeriods||[];if(!canAction('finance','edit'))return rows.length?`<div class="panel"><h2>${state.lang==='ar'?'الفترات المالية':'Financial periods'}</h2>${table(rows)}</div>`:'';return `<div class="panel"><h2>${state.lang==='ar'?'إقفال الفترات المالية':'Financial period closing'}</h2><p class="muted">${state.lang==='ar'?'يمنع النظام الإقفال إذا وجدت حركات غير مراجعة أو قيود غير متوازنة. فك الإقفال متاح فقط للشريك أو المدير المالي.':'Closing is blocked while transactions are unreviewed or journals are unbalanced. Reopening is restricted to partners and the financial manager.'}</p><form id="periodCloseForm"><div class="form-grid"><label class="field">${state.lang==='ar'?'الفترة':'Period'}<input name="period" type="month" required></label><label class="field field-wide">${state.lang==='ar'?'سبب الإقفال':'Closing reason'}<input name="reason" required></label></div><div class="actions"><button class="primary">${state.lang==='ar'?'مراجعة وإقفال الفترة':'Validate and close period'}</button></div></form><form id="periodReopenForm"><div class="form-grid"><label class="field">${state.lang==='ar'?'فك فترة':'Reopen period'}<select name="period" required><option value=""></option>${rows.filter(x=>x['الحالة']==='LOCKED').map(x=>`<option>${esc(x['الفترة'])}</option>`).join('')}</select></label><label class="field field-wide">${state.lang==='ar'?'سبب فك الإقفال':'Reopening reason'}<input name="reason" required></label></div><button class="secondary">${state.lang==='ar'?'فك الإقفال':'Reopen'}</button></form>${table(rows)}</div>`}
const financePeriodBase_=financeSmart;financeSmart=function(){const base=financePeriodBase_().replace(/<label class="field">[^<]*<select name="معرف حساب الأستاذ"[\s\S]*?<\/select><\/label>/,'');return `${base}${financialPeriodPanel_()}`};
document.addEventListener('submit',async e=>{if(!['periodCloseForm','periodReopenForm'].includes(e.target.getAttribute('id')))return;e.preventDefault();e.stopImmediatePropagation();try{const action=e.target.getAttribute('id')==='periodCloseForm'?'finance.period.close':'finance.period.reopen',r=await api(action,obj(e.target));if(!r.ok)throw new Error(msg(r));const list=await api('finance.periods.list',{});if(!list.ok)throw new Error(msg(list));state.data.financialPeriods=list.data;state.notice={type:'ok',text:state.lang==='ar'?'تم تحديث حالة الفترة المالية.':'Financial period status updated.'};render()}catch(error){fail(error)}},true);

finance=function(){const f=state.data.financeDashboard;if(!f)return `<h1>${t('finance')}</h1><div class="panel empty">${t('none')}</div>`;const typeName={BANK:['حساب بنكي','Bank account'],CASH:['خزنة / كاش','Cash vault'],CUSTODY:['عهدة نقدية','Cash custody'],WALLET:['محفظة إلكترونية','E-wallet']},accounts=f.balances||[],warnings=f.warnings||[];return `<h1>${t('finance')}</h1><div id="financeOutput" class="formal-report">${reportHeader_(state.lang==='ar'?'تقرير السيولة والحد الآمن للسحب':'Liquidity and safe-withdrawal report',(state.lang==='ar'?'حتى ':'As of ')+esc(String(f.generatedAt||'').slice(0,10)))}<div class="finance-account-grid">${accounts.map(a=>`<article class="finance-account"><small>${state.lang==='ar'?(typeName[a.type]?.[0]||a.type):(typeName[a.type]?.[1]||a.type)}</small><h3>${esc(a.name)}</h3><strong>${money(a.balance)}</strong><span>${esc(a.currency||'EGP')} · ${state.lang==='ar'?'آخر تحديث':'Updated'} ${esc(String(a.lastUpdate||'—').slice(0,10))}</span></article>`).join('')}</div><div class="grid report-totals"><article class="card">${state.lang==='ar'?'السيولة المالية المسجلة':'Recorded liquidity'}<strong>${money(f.bookBalance)}</strong></article><article class="card">${state.lang==='ar'?'دفعات عملاء غير مكتسبة ومحجوزة':'Unearned client funds reserved'}<strong>${money(f.clientFundsReserve)}</strong></article><article class="card">${state.lang==='ar'?'التزامات موردين مفتوحة':'Open vendor commitments'}<strong>${money(f.vendorReserve)}</strong></article><article class="card">${state.lang==='ar'?'مرتبات الشهر القادم':'Next month payroll'}<strong>${money(f.payrollReserve)}</strong></article><article class="card">${state.lang==='ar'?'إيجار الشهر القادم':'Next month rent'}<strong>${money(f.rentReserve)}</strong></article><article class="card">${state.lang==='ar'?'مصروفات دورية أخرى':'Other recurring expenses'}<strong>${money(f.recurringExpenseReserve)}</strong></article><article class="card">${state.lang==='ar'?'ضرائب مستحقة':'Tax reserve'}<strong>${money(f.taxReserve)}</strong></article><article class="card">${state.lang==='ar'?'احتياطي الطوارئ':'Emergency reserve'}<strong>${money(f.buffer)}</strong></article><article class="card">${state.lang==='ar'?'الرصيد بعد كل الحجوزات':'Balance after all reserves'}<strong>${money(f.netAfterReserves)}</strong></article><article class="card">${state.lang==='ar'?'الحد الأقصى الآمن للسحب الآن':'Maximum safe withdrawal now'}<strong>${money(f.safeWithdrawal)}</strong></article><article class="card">${state.lang==='ar'?'عجز التغطية إن وجد':'Funding gap, if any'}<strong>${money(f.fundingGap)}</strong></article></div><div class="report-note">${state.lang==='ar'?'الحسبة: السيولة المسجلة − دفعات العملاء غير المكتسبة − التزامات الموردين المفتوحة − مرتبات وإيجار الشهر القادم − المصروفات الدورية − الضرائب − احتياطي الطوارئ. الرقم السالب يظهر كعجز تغطية، بينما السحب المسموح لا يقل عن صفر.':'Formula: recorded liquidity minus unearned client funds, open vendor commitments, next-month payroll and rent, recurring expenses, taxes and emergency reserve.'}</div>${warnings.length?`<div class="notice error">${warnings.map(esc).join('<br>')}</div>`:''}<footer class="report-footer">FOOZIX Live · Arte Divino</footer></div><div class="actions no-print"><button id="printFinance" class="secondary">PDF / ${state.lang==='ar'?'طباعة ملخص السيولة والأرصدة':'Print liquidity and balances summary'}</button></div>`}

function uniqueEmployees_(rows){const seen=new Set();return (rows||[]).filter(e=>{const email=String(e['البريد']||'').trim().toLowerCase(),name=String(e['الاسم العربي']||e['الاسم الإنجليزي']||'').trim().toLowerCase(),key=email?'email:'+email:'name:'+name;if(!name&&!email)return false;if(seen.has(key))return false;seen.add(key);return true})}
function normalizeEmployeeState_(){if(Array.isArray(state.data.employees))state.data.employees=uniqueEmployees_(state.data.employees)}
const loadWithEmployeeDedup_=load;load=async function(){await loadWithEmployeeDedup_();normalizeEmployeeState_()};
const bootstrapWithEmployeeDedup_=applyBootstrap_;applyBootstrap_=function(data){if(data&&data.data&&Array.isArray(data.data.employees))data.data.employees=uniqueEmployees_(data.data.employees);const result=bootstrapWithEmployeeDedup_(data);normalizeEmployeeState_();return result};
const printPreparedBase_=printPrepared_;printPrepared_=function(){const reports=[...document.querySelectorAll('.formal-report')].filter(x=>x.textContent.trim());if(!reports.length)return printPreparedBase_();const target=reports[reports.length-1];reports.forEach(x=>x.classList.toggle('print-target',x===target));document.body.classList.add('single-report-print');window.print();setTimeout(()=>{document.body.classList.remove('single-report-print');reports.forEach(x=>x.classList.remove('print-target'))},500)};

