async function loadTransactionHistory_(panel,page,search){
  const output=panel.querySelector('#transactionHistoryResults'),button=panel.querySelector('button[type="submit"]');button.disabled=true;output.textContent=state.lang==='ar'?'جارٍ تحميل الحركات…':'Loading transactions…';
  try{const response=await api('list',{module:'transactions',sheet:'الحركات اليومية',page,pageSize:50,search});if(!response.ok)throw new Error(msg(response));if(!panel.isConnected)return;const result=response.data;
    const name=(list,idField,id)=>{const row=(state.data[list]||[]).find(x=>String(x[idField])===String(id));return row?(row['الاسم العربي']||row['الاسم الإنجليزي']||id):id||'—'};
    output.innerHTML=`<p>${state.lang==='ar'?'إجمالي النتائج':'Total results'}: ${Number(result.total||0)} — ${state.lang==='ar'?'صفحة':'Page'} ${page}</p>${(result.items||[]).map(row=>`<article class="approval-card"><h3>${esc(name('projects','معرف المشروع',row['معرف المشروع']))} — ${money(row['المبلغ الأساسي']||row['المبلغ']||0)}</h3><p>${esc(row['الوصف']||row['ملاحظات']||'')} — ${esc(String(row['تاريخ العملية']||'').slice(0,10))}</p><p>${esc(row['المرجع']||'')}</p><button type="button" class="transaction-correct" data-id="${esc(row['معرف الحركة'])}">${state.lang==='ar'?'فتح وتعديل الحركة':'Open and edit transaction'}</button></article>`).join('')||`<p>${state.lang==='ar'?'لا توجد نتائج':'No results'}</p>`}<div class="actions"><button type="button" data-history-page="${page-1}" ${page<=1?'disabled':''}>${state.lang==='ar'?'السابق':'Previous'}</button><button type="button" data-history-page="${page+1}" ${page*50>=Number(result.total||0)?'disabled':''}>${state.lang==='ar'?'التالي':'Next'}</button></div>`;
    output.querySelectorAll('[data-history-page]').forEach(b=>b.onclick=()=>loadTransactionHistory_(panel,Number(b.dataset.historyPage),search));
  }catch(error){if(panel.isConnected)output.textContent=error.message}finally{if(button.isConnected)button.disabled=false}
}
