function entityEditModule_(entity){return {client:'clients',project:'projects',party:'parties',employee:'employees',asset:'assets',cashAccount:'finance',agreement:'agreements',finishItem:'settings',expenseItem:'settings'}[entity]}
function refreshMasterReadouts_(){
  // Refresh derived tables without replacing open forms or navigating away.
  const main=document.querySelector('main');if(!main)return;
  const preview=document.createElement('div');preview.innerHTML=view();
  const current=[...main.querySelectorAll('table')],fresh=[...preview.querySelectorAll('table')];
  if(current.length===fresh.length)current.forEach((table,index)=>table.replaceWith(fresh[index]));
}
