  const ar=state.lang==='ar',headers=ar?['الطرف / المشروع','قيمة الاتفاق الحالية','المدفوع','المتبقي من الاتفاق','الأعمال المعتمدة','المستحق حاليًا','القيمة الأصلية','التعديلات','الحالة','الكمية المتفق عليها','الكمية المعتمدة','سعر الوحدة']:['Party / project','Current agreement value','Paid','Remaining agreement value','Certified work','Currently due','Original value','Amendments','Status','Agreed quantity','Certified quantity','Unit rate'];
