  const controls=`<section class="panel no-print"><div class="form-grid"><label class="field">${ar?'العميل':'Client'}<select id="dashboardClient">${workspaceOptions_(state.data.clients||[],'معرف العميل',filter.client)}</select></label><label class="field">${ar?'المشروع':'Project'}<select id="dashboardProject">${workspaceOptions_(projects,'معرف المشروع',filter.project)}</select></label><label class="field">${ar?'المورد / المقاول':'Supplier / contractor'}<select id="dashboardParty">${workspaceOptions_(state.data.parties||[],'معرف الطرف',filter.party)}</select></label></div></section>`;
  let financial='';const original=state.data.projectFinancialSummary;
  if(original){
    const visible=new Set(projects.map(x=>String(x['معرف المشروع']))),keep=x=>(!filter.client||visible.has(String(x['معرف المشروع'])))&&(!filter.project||String(x['معرف المشروع'])===filter.project);
    const active=original.active.filter(keep),archived=original.archived.filter(keep),totals={};
    Object.keys(original.totals).forEach(k=>totals[k]=active.reduce((sum,x)=>sum+Number(x[k]||0),0));
    try{state.data.projectFinancialSummary={...original,active,archived,totals};financial=financialProjectDashboard_();}finally{state.data.projectFinancialSummary=original;}
  }
  const visibleProjects=new Set(projects.map(x=>String(x['معرف المشروع'])));
  const agreements=(state.data.agreements||[]).filter(x=>(!filter.client||visibleProjects.has(String(x['معرف المشروع'])))&&(!filter.project||String(x['معرف المشروع'])===filter.project)&&(!filter.party||String(x['معرف الطرف'])===filter.party));
  const balances=canAction('agreements','view')?`<section class="panel"><h2>${ar?'الاتفاقات — المتفق عليه والمدفوع والمتبقي':'Agreements — agreed, paid and remaining'}</h2>${agreementTable(agreements)}</section>`:'';
