function openDuplicateCancellationDialog_(id,sourceDialog){
  const dialog=document.createElement('dialog');dialog.className='panel';dialog.style.cssText='width:min(700px,95vw);max-height:90vh;overflow:auto';
  dialog.innerHTML=`<h2>${state.lang==='ar'?'إلغاء حركة كتسجيل مكرر':'Cancel a duplicate movement'}</h2><p>${state.lang==='ar'?'لن تُحذف الحركة. إذا ثبت أنها تكرار، سينشئ النظام قيد عكس ويحفظ سجل المراجعة.':'The movement will not be deleted. Once confirmed as a duplicate, the system creates an audited reversing entry.'}</p><form id="duplicateDialogForm"><label class="field">${state.lang==='ar'?'معرف الحركة الأصلية التي ستبقى':'ID of the movement to retain'}<input name="retainedId" required></label><button type="button" id="duplicateDialogPreview">${state.lang==='ar'?'فحص التطابق':'Check match'}</button><output role="status"></output><label class="field">${state.lang==='ar'?'سبب الإلغاء':'Cancellation reason'}<input name="reason" required></label><label class="check-line"><input name="confirmed" type="checkbox" required><span>${state.lang==='ar'?'أؤكد أنها نفس الدفعة وليست دفعتين منفصلتين':'I confirm these are the same payment, not two separate payments'}</span></label><div class="actions"><button type="submit" disabled>${state.lang==='ar'?'إلغاء الأثر بقيد عكسي':'Reverse duplicate effect'}</button><button type="button" id="duplicateDialogClose">${state.lang==='ar'?'إغلاق':'Close'}</button></div></form>`;
  const form=dialog.querySelector('form'),close=()=>{dialog.close();dialog.remove()};dialog.querySelector('#duplicateDialogClose').onclick=close;
  dialog.querySelector('#duplicateDialogPreview').onclick=async()=>{const output=form.querySelector('output');try{const response=await api('transaction.duplicatePreview',{id,retainedId:form.elements.retainedId.value.trim()});if(!response?.ok)throw new Error(msg(response));form._duplicatePreview=response.data;output.textContent=[response.data.project,response.data.date,money(response.data.amount),response.data.account].filter(Boolean).join(' — ');form.querySelector('button[type=submit]').disabled=response.data.status!=='POSTED';}catch(error){output.textContent=error.message;}};
  form.onsubmit=async event=>{event.preventDefault();if(!form._duplicatePreview||!form.reportValidity())return;const output=form.querySelector('output'),button=form.querySelector('button[type=submit]');try{button.disabled=true;const response=await api('transaction.cancelDuplicate',{...form._duplicatePreview,reason:form.elements.reason.value,confirmed:form.elements.confirmed.checked});if(!response?.ok)throw new Error(msg(response));output.textContent=(state.lang==='ar'?'تم الإلغاء بقيد عكسي: ':'Cancelled with reversing entry: ')+response.data.journalId;sourceDialog?.close();sourceDialog?.remove();}catch(error){output.textContent=error.message;button.disabled=false;}};
  document.body.append(dialog);dialog.showModal();
}
reports=function(){const html=duplicateCancellationReportBase_();if(!['SUPER_ADMIN','FINANCIAL_MANAGER'].includes(state.profile.role)||!canAction('transactions','edit')||!canAction('finance','edit'))return html;return html+`<details class="panel"><summary>إلغاء تسجيل مكرر مؤكد</summary><p>يعكس قيد السطر المكرر فقط ويحفظ تاريخه، ولا يحذف الحركة الأصلية ولا ينشئ مرتجعًا أو تحويلًا بنكيًا فعليًا. الإلغاء ليس اعتماد مراجعة.</p><form id="duplicateCancellation"><label class="field">معرف السطر المكرر<input name="id" required></label><label class="field">معرف الحركة الأصلية التي ستبقى<input name="retainedId" required></label><button type="button" id="previewDuplicateCancellation">فحص التطابق</button><output class="duplicate-preview" role="status"></output><label class="field">سبب الإلغاء<input name="reason" required></label><label><input name="confirmed" type="checkbox" required>أؤكد أنه نفس الدفع، وليس دفعتين منفصلتين</label><button type="submit" disabled>إلغاء أثر السطر المكرر</button></form></details>`;};
document.addEventListener('input',event=>{const form=event.target.form;if(form?.getAttribute('id')==='duplicateCancellation'&&['id','retainedId'].includes(event.target.name)){form._duplicatePreview=null;form.querySelector('button[type=submit]').disabled=true;}});
document.addEventListener('click',async event=>{const button=event.target.closest('#previewDuplicateCancellation');if(!button)return;const form=button.form;try{button.disabled=true;const response=await api('transaction.duplicatePreview',{id:form.elements.namedItem('id').value.trim(),retainedId:form.elements.namedItem('retainedId').value.trim()});if(!response?.ok)throw new Error(msg(response));form._duplicatePreview=response.data;form.querySelector('output').textContent=[response.data.project,response.data.date,money(response.data.amount),response.data.account,'المكرر: '+response.data.description,'الأصلية: '+response.data.retainedDescription,'مستند الأصلية: '+response.data.retainedDocument].join(' — ');form.querySelector('button[type=submit]').disabled=response.data.status!=='POSTED';}catch(error){form.querySelector('output').textContent=error.message;}finally{button.disabled=false;}});
window.addEventListener('submit',async event=>{const form=event.target;if(form.getAttribute('id')!=='duplicateCancellation')return;event.preventDefault();event.stopImmediatePropagation();if(!form._duplicatePreview||form.dataset.saving==='true'||!form.reportValidity())return;const button=form.querySelector('button[type=submit]');form.dataset.saving='true';button.disabled=true;try{const response=await api('transaction.cancelDuplicate',{...form._duplicatePreview,reason:form.elements.namedItem('reason').value,confirmed:form.elements.namedItem('confirmed').checked});if(!response?.ok)throw new Error(msg(response));form.querySelector('output').textContent='تم إلغاء أثر السطر المكرر بقيد عكسي '+response.data.journalId+'؛ الحركة الأصلية لم تتغير.';form._duplicatePreview=null;}catch(error){form.querySelector('output').textContent=error.message;button.disabled=false;}finally{form.dataset.saving='false';}},true);

